/* planet-house.js — Session 8b (2026-09-26): natal planet-in-house results, 9 planets x 12 houses x 5 languages.
   AKSRA: English written from two independent compilations (B.V. Raman's classical summary + a modern 108-combination guide),
   softened to tendencies (no fatalism); harsh classical phrasings omitted. The UI adds chart-specific modifiers (dignity,
   functional nature, strength, aspects). Translations reviewed for script/terminology. */
window.ZAICHA_PH = {"version": 1, "sources": [{"title": "B.V. Raman, Hindu Predictive Astrology — planets in the 12 houses (108-entry summary, VedAstro)", "url": "https://vedastro.org/blog/Hindu-Predictive-Astrology-Part-19-Planets-in-All-12-Houses.html"}, {"title": "Planets in Houses in Vedic Astrology — all 108 combinations (Jagannath Hora)", "url": "https://jagannathhora.com/planets-in-houses-vedic-astrology/"}, {"title": "Mantreswara, Phaladeepika ch. 8 — effects of planets in the houses (wisdomlib)", "url": "https://www.wisdomlib.org/hinduism/book/phaladeepika-by-mantreswara-text-and-translation/d/doc1621580.html"}], "theme": {"en": ["self, body and vitality", "wealth, family and speech", "courage, effort and younger siblings", "home, mother and inner peace", "children, intelligence and creativity", "disease, enemies, debts and service", "marriage and partnerships", "longevity, hidden matters and sudden events", "fortune, dharma, father and higher learning", "career, status and public life", "gains, income and friends", "losses, expenses, foreign lands and liberation"], "ur": ["ذات، جسم اور توانائی", "دولت، خاندان اور گفتگو", "ہمت، محنت اور چھوٹے بہن بھائی", "گھر، والدہ اور باطنی سکون", "اولاد، ذہانت اور تخلیقی صلاحیت", "بیماری، دشمن، قرض اور ملازمت", "شادی اور شراکت داری", "طویل عمر، پوشیدہ معاملات اور اچانک واقعات", "قسمت، دھرم، والد اور اعلیٰ تعلیم", "کیریئر، رتبہ اور عوامی زندگی", "فائدہ، آمدنی اور دوست", "نقصان، اخراجات، بیرونی ممالک اور نجات"], "hi": ["स्वयं, शरीर और जीवनी शक्ति", "धन, परिवार और वाणी", "साहस, प्रयास और छोटे भाई-बहन", "घर, माता और आंतरिक शांति", "संतान, बुद्धि और रचनात्मकता", "रोग, शत्रु, ऋण और सेवा", "विवाह और साझेदारियाँ", "दीर्घायु, गुप्त विषय और अचानक घटनाएँ", "भाग्य, धर्म, पिता और उच्च शिक्षा", "करियर, प्रतिष्ठा और सार्वजनिक जीवन", "लाभ, आय और मित्र", "हानि, खर्च, विदेश और मोक्ष"], "ar": ["الذات، الجسد والحيوية", "المال، الأسرة والكلام", "الشجاعة، الجهد والإخوة الأصغر", "المنزل، الأم والسلام الداخلي", "الأولاد، الذكاء والإبداع", "المرض، الأعداء، الديون والخدمة", "الزواج والشراكات", "طول العمر، الأمور الخفية والأحداث المفاجئة", "الحظ، الدارما، الأب والتعليم العالي", "المسيرة المهنية، المكانة والحياة العامة", "المكاسب، الدخل والأصدقاء", "الخسائر، النفقات، البلاد الأجنبية والخلاص"], "zh": ["自我、身体与活力", "财富、家庭与言语", "勇气、努力与弟妹", "家庭、母亲与内心平静", "子女、智慧与创造力", "疾病、敌人、债务与服务", "婚姻与合作关系", "寿命、隐秘事务与突发事件", "福气、正法（dharma）、父亲与高等教育", "事业、地位与公众生活", "收益、收入与朋友", "损失、开支、异国他乡与解脱"]}, "text": {"en": {"Sun": ["A strong sense of self, leadership and a dignified presence; good vitality and a wish to be respected. Watch pride and a hot temper, and care for the head, eyes and heart.", "Earnings through authority, government or the father's side, and a confident, commanding way of speaking. Watch harsh words in the family and spending to keep up status.", "Courage, initiative and success through one's own efforts; fame through communication, writing or short journeys. Relations with younger siblings may be competitive.", "Ambition for property and a respectable home, success away from the birthplace. Peace at home can be disturbed by ego clashes; the heart and mother's health need care.", "Sharp intelligence, creative and advisory ability, interest in politics or speculation. Children may be few or come later; avoid rash speculation.", "One of the Sun's best houses: victory over rivals, success in service, administration and competition, good resistance to illness. Watch overwork and conflicts at work.", "Partnerships and marriage with a strong-willed or status-conscious partner; gains through dealings with the public. Ego in relationships can delay marriage or cause friction.", "Interest in hidden subjects, research and inheritance; sudden changes in status. Care for the eyes and general vitality; avoid unnecessary risks.", "Good fortune, dharma and respect for teachers and the father; gains through higher learning, law or religion. Can make one self-righteous or distant from the father.", "Excellent for career: authority, fame, government or leadership positions and public recognition — the Sun gains directional strength here. Guard against arrogance at work.", "Gains without much effort, influential friends and fulfilment of ambitions; income through government or senior people. Friendships may be status-based.", "Interest in spirituality, foreign lands and solitude; expenses on status, travel or charity. Self-confidence and eyesight need care; recognition may come late."], "Moon": ["An attractive, sensitive and sociable nature, popular with people and changeable in mood. Emotional balance depends on the Moon's strength (waxing or waning).", "Pleasant, sweet speech, family affection and gains through the public, food, liquids or trade. Income may fluctuate with the mind's moods.", "Imaginative communication, love of travel and a caring bond with siblings; success in writing, media or short journeys. Mood swings can scatter effort.", "One of the Moon's best houses (directional strength): a happy home, comfort, vehicles, a close bond with the mother and peace of mind.", "Emotional intelligence, creativity and affection for children (often daughters); gains through the public or advisory roles. Guard against romantic over-sensitivity.", "A caring, service-minded nature, suited to healthcare or public service; the digestion and stomach need care, and emotional stress can affect health.", "An emotional, attractive partner and a strong need for companionship; success in public dealings. The partner's moods or changeability need patience.", "A deep, intuitive and secretive mind; interest in the occult and possible inheritance. Emotional ups and downs and care for the eyes and fluids in the body.", "A devout, popular and fortunate nature, love of pilgrimage and learning, good children and support from the mother. Travel abroad is likely.", "Public popularity, success in business, hospitality, public-facing or caring professions; a changing career path with many moves. Reputation depends on the Moon's strength.", "Many friends (often women), fulfilment of wishes and steady gains through the public and networks. Income may vary but tends to rise over time.", "A private, imaginative inner life, attraction to foreign places, charity and spiritual retreat. Sleep, expenses and emotional isolation need care."], "Mars": ["Energy, courage and a bold, active personality; natural leadership in physical or technical fields. Watch impatience, anger and minor injuries or scars to the head. (Counts for Mangal Dosha.)", "Blunt, forceful speech and money earned through effort, land or technical work. Quarrels in the family and impulsive spending are the main cautions. (Counts for Mangal Dosha in South Indian practice.)", "One of Mars's best houses: great courage, initiative and success through one's own effort; good in sports, military, police or engineering. Relations with siblings may be competitive.", "Property, land and vehicles through effort; a strong wish for one's own home. Peace at home and the mother's health need care; avoid domestic arguments. (Counts for Mangal Dosha.)", "Sharp, strategic intelligence and a competitive creative drive; interest in sports or technology. Children may come with some difficulty; avoid reckless speculation.", "Excellent for defeating rivals and winning competitions or legal matters; success in service, surgery, police or army. Watch blood pressure and inflammation.", "A passionate, energetic partner and a bold approach to partnerships and business. Friction or dominance in marriage needs care; patience is essential. (Counts for Mangal Dosha.)", "Interest in research, surgery, occult or crisis work; possible inheritance or sudden gains. Guard against accidents, operations and conflicts over joint money. (Counts for Mangal Dosha.)", "An active, principled nature that fights for beliefs; gains through land, trade or travel. Differences with the father or teachers are possible; avoid dogmatism.", "Excellent for career (directional strength): energy, command and achievement in engineering, military, sports, surgery or management; can found institutions. Watch conflicts with authority.", "Strong gains through effort, property and influential friends; ambitions are realised through hard work. Elder siblings or friends may be competitive.", "Energy spent on foreign affairs, hospitals, spiritual practice or hidden work; expenses can be high. Care for sleep, anger and hidden enemies. (Counts for Mangal Dosha.)"], "Mercury": ["A clever, witty, youthful and communicative personality; good learning ability and a talent for trade, writing or speaking. Can be restless or nervous.", "Articulate, persuasive speech, skill with languages, accounts and trade; earnings through intellect. Guard against cleverness turning into argument.", "Excellent communication, writing, media, commerce and short travel; tactful and quick-thinking. Relations with siblings are usually intellectual and lively.", "Education, a well-read home, success in property, vehicles or literary work and a caring mother. Can bring mental restlessness at home.", "Sharp intelligence, skill in mathematics, analysis and advisory or administrative roles; good students. Children may be intelligent and communicative.", "Analytical, detail-oriented work: accounts, law, health or service; able to out-argue opponents. Watch nervous tension, skin and digestive sensitivity.", "A youthful, intelligent partner and success in trade, negotiation and business partnerships. Relationships benefit from good communication.", "Research, investigation, occult study and long life; possible gains from inheritance or insurance. Worry and secretive thinking need balance.", "Higher learning, philosophy, law, publishing and teaching; many interests and creative, scientific ability. Can over-intellectualise faith.", "Career through communication, trade, IT, accounting, writing or teaching; intelligent and fortunate in work — Mercury gains directional strength in the 1st, but does well here too.", "Gains through trade, networks, mathematics and communication; many friends and fulfilled wishes. Income may come from several sources.", "A reflective, philosophical mind, interest in foreign languages, research or spirituality. Worry, expenses on learning and communication gaps need care."], "Jupiter": ["One of Jupiter's best houses (directional strength): wisdom, dignity, good character and a protective influence on the whole chart; respected as a guide or teacher. Watch weight gain and over-optimism.", "Wealth, a cultured family, fluent and truthful speech and success in teaching, law or finance. Money tends to accumulate over time.", "Wisdom in communication and writing; good relations with siblings. Efforts can be slow or Jupiter's generosity reduced here; consistent effort is needed.", "A happy, comfortable home, good education, property and vehicles, and a caring mother; inner contentment. One of Jupiter's strong angular positions.", "Excellent for intelligence, children, education, advice and spiritual practice; good judgement and a respected position.", "Victory through wisdom and ethics, suited to service, law, medicine or counselling. Classical texts count it weaker here; watch debts, weight and liver health.", "A wise, virtuous and often educated partner; success in partnerships, law and consulting. Jupiter aspects the Lagna from here, supporting health and character.", "Long life, interest in spiritual and hidden knowledge, possible inheritance. Classical texts count it less comfortable; results come after obstacles.", "One of the most fortunate placements: dharma, faith, good teachers, children, generosity and luck through higher learning, law, religion or travel.", "Honourable career in teaching, law, finance, advice or administration; respected, ethical and able to found institutions. Promotions tend to come steadily.", "Substantial gains, fulfilment of wishes, learned and influential friends; income rises with age. A very beneficial position for prosperity.", "Generosity, charity, spiritual growth and interest in moksha; expenses on good causes, travel abroad. Material savings may need care."], "Venus": ["Charm, beauty, artistic taste and a pleasant, sociable nature; comforts and good fortune in relationships. Watch indulgence and vanity.", "Wealth, a happy family, sweet speech and earnings through arts, luxury, beauty or finance; love of good food. Guard against overspending.", "Artistic and creative communication, a love of music and media; affectionate siblings. Courage may be soft; success comes through charm and skill.", "One of Venus's best houses: a beautiful home, vehicles, comforts, a loving mother and domestic happiness; good education in the arts.", "Creativity, romance, artistic intelligence and joy through children; success in entertainment, design or speculation with care.", "Classical texts count Venus weak here: relationships can face obstacles or come through work; suited to service in beauty, health or hospitality. Watch sugar and indulgence.", "The natural house of marriage: an attractive, affectionate partner and pleasure in partnership, business and public dealings. Balance romance with responsibility.", "Gains through a spouse, inheritance or joint resources; interest in hidden pleasures or occult. Guard the reproductive health and secret affairs.", "Fortune through arts, a cultured spouse or foreign connections; generous, refined and devoted. Travel for pleasure or learning.", "Career in arts, fashion, design, media, hospitality, finance or diplomacy; public charm and popularity. Success through women or partners.", "Gains through arts, luxury, partners and influential friends; fulfilment of desires and a comfortable income.", "Classically a favoured place for Venus: comforts of the bed and rest, foreign travel, spiritual devotion through beauty. Watch overspending and secret relationships."], "Saturn": ["A serious, mature, hard-working and patient nature; success comes slowly but lasts. Watch pessimism, loneliness and chronic health issues; strong if Saturn is in its own or exalted sign.", "Wealth built slowly through discipline and saving; a measured, careful way of speaking. Family responsibilities, delayed education and eyesight need care.", "One of Saturn's best houses: perseverance, courage through endurance and success after sustained effort; long-term planning. Relations with siblings can be distant.", "Responsibilities at home, delays in property or vehicles and a serious bond with the mother; peace of mind grows with age. Success can come away from the birthplace.", "Serious, practical intelligence and discipline in study; children may be delayed or few, and speculation should be avoided.", "Excellent for defeating rivals through persistence; suited to service, labour, law or healthcare. Health issues tend to be chronic but manageable with discipline.", "A mature, loyal or older partner; marriage may be delayed but stable. Success in long-term business partnerships (directional strength for Saturn).", "Long life, interest in research and hidden subjects; slow, lasting transformation. Delays in inheritance and chronic ailments need patience.", "Disciplined faith and respect for tradition; fortune comes later in life through effort. Differences with the father or teachers are possible.", "Very strong for career: hard work, responsibility, authority built over time, success in administration, law, engineering or large organisations (Shasha yoga if in own/exalted sign).", "Steady, lasting gains and wealth through persistence; influential, older or senior friends. Income rises with age.", "Expenses, foreign residence, work in hospitals, ashrams or isolated places; spiritual discipline. Sleep, the feet and hidden losses need care."], "Rahu": ["An unconventional, ambitious and magnetic personality, drawn to new ideas, technology or foreign culture. Watch confusion about identity and health that is hard to diagnose.", "Unusual sources of income, skill with foreign languages or media; bold speech. Watch exaggeration, family disputes and irregular eating.", "One of Rahu's best houses: courage, ambition, success in media, technology, marketing or communication, and bold initiative.", "Settlement away from the birthplace or abroad, an unusual home life; interest in property or vehicles. Peace of mind and the mother's health need care.", "An inventive, unconventional intelligence; interest in speculation, technology or research. Children may come unusually or with delay; avoid risky bets.", "An excellent Rahu placement: victory over rivals, success in competition, service, medicine or law through unconventional means.", "An unconventional or foreign partner and business with foreign links; ambition in partnerships. Clarity and trust in relationships need care.", "Deep interest in research and the occult; sudden gains or losses and unexpected events. Caution with risky ventures and hidden health issues.", "Unconventional or foreign beliefs and teachers, travel abroad; can form Raja yoga when well connected. Avoid conflict with elders over faith.", "Ambitious, unconventional career, success with technology, foreign firms or mass media, and a strong drive for status. Guard reputation against shortcuts.", "Generally one of Rahu's most beneficial places: large gains, powerful friends and fulfilment of ambitions, often through technology or foreign networks.", "Foreign residence, spiritual or occult pursuits and unusual expenses; sleep disturbances and hidden losses need care."], "Ketu": ["A detached, spiritual and intuitive personality with sharp insight; can feel unsure of identity. Care for general vitality.", "Detachment from wealth or family, unusual speech or diet; spiritual learning. Savings and family harmony need attention.", "Courage, strong intuition and success through independent effort; interest in mysticism or unusual skills. Relations with siblings may be distant.", "Detachment from home or the birthplace, frequent changes of residence; inner search for peace. The mother's health needs care.", "Intuitive, research-minded intelligence and past-life spiritual merit; children or romance may bring challenges or delays.", "One of Ketu's stronger houses: victory over enemies, sharp instincts, success in healing, research or service.", "A spiritual or unusual partnership; detachment or misunderstandings in marriage and business need care.", "Deep interest in the occult, research and hidden matters; sudden transformations. Guard against accidents and hidden illnesses.", "Unconventional faith, detachment from rituals and deep spiritual insight; differences with teachers or the father are possible.", "Sudden changes in career, work guided by intuition or spiritual interests; research, technology or healing. Avoid abrupt decisions.", "Gains that come and go, detachment from desires, witty and intelligent; a few meaningful friendships.", "Classically linked with moksha: spiritual liberation, foreign lands and retreats; expenses on spiritual causes."]}, "ur": {"Sun": ["خود اعتمادی، قائدانہ صلاحیت اور باوقار شخصیت؛ اچھی توانائی اور عزت پانے کی خواہش۔ غرور اور تیز مزاجی سے بچیں، اور سر، آنکھوں اور دل کا خیال رکھیں۔", "اختیار، سرکار یا والد کی طرف سے آمدنی، اور پراعتماد و رعب دار انداز گفتگو۔ خاندان میں سخت الفاظ اور رتبہ برقرار رکھنے کے لیے زیادہ خرچ سے بچیں۔", "ہمت، پہل کاری اور اپنی محنت سے کامیابی؛ رابطے، تحریر یا مختصر سفر کے ذریعے شہرت۔ چھوٹے بہن بھائیوں کے ساتھ تعلقات میں مقابلے بازی ہو سکتی ہے۔", "جائیداد اور باوقار گھر کی خواہش، جائے پیدائش سے دور کامیابی۔ انا کے ٹکراؤ سے گھر کا سکون متاثر ہو سکتا ہے؛ دل اور والدہ کی صحت کا خیال رکھیں۔", "تیز ذہانت، تخلیقی اور مشاورتی صلاحیت، سیاست یا قیاس آرائی (سٹے بازی) میں دلچسپی۔ اولاد کم ہو سکتی ہے یا دیر سے ہو؛ جلد بازی میں سٹے بازی سے گریز کریں۔", "سورج کے بہترین خانوں میں سے ایک: مخالفین پر فتح، ملازمت، انتظامیہ اور مقابلوں میں کامیابی، بیماریوں کے خلاف اچھی مزاحمت۔ زیادہ کام اور کام کی جگہ پر تنازعات سے بچیں۔", "مضبوط ارادے یا رتبے کے شعور رکھنے والے ساتھی کے ساتھ شراکت داری اور شادی؛ عوام سے لین دین میں فائدہ۔ رشتوں میں انا شادی میں تاخیر یا رنجش کا باعث بن سکتی ہے۔", "مخفی موضوعات، تحقیق اور وراثت میں دلچسپی؛ رتبے میں اچانک تبدیلیاں۔ آنکھوں اور مجموعی توانائی کا خیال رکھیں؛ غیر ضروری خطرات سے بچیں۔", "اچھی قسمت، دھرم (دین داری) اور اساتذہ و والد کا احترام؛ اعلیٰ تعلیم، قانون یا مذہب کے ذریعے فائدہ۔ یہ انسان کو خود پسند یا والد سے دور کر سکتا ہے۔", "کیریئر کے لیے بہترین: اختیار، شہرت، سرکاری یا قائدانہ عہدے اور عوامی پذیرائی — سورج یہاں دِگ بل (سمتی قوت) حاصل کرتا ہے۔ کام کی جگہ پر تکبر سے بچیں۔", "بغیر زیادہ محنت کے فائدہ، بااثر دوست اور خواہشات کی تکمیل؛ سرکار یا اعلیٰ عہدے دار لوگوں سے آمدنی۔ دوستیاں رتبے کی بنیاد پر ہو سکتی ہیں۔", "روحانیت، بیرونی ممالک اور تنہائی میں دلچسپی؛ رتبے، سفر یا خیرات پر اخراجات۔ خود اعتمادی اور بینائی کا خیال رکھیں؛ پذیرائی دیر سے مل سکتی ہے۔"], "Moon": ["دلکش، حساس اور ملنسار طبیعت، لوگوں میں مقبول اور موڈ میں تبدیلی کا رجحان۔ جذباتی توازن چاند کی طاقت (بڑھتا یا گھٹتا چاند) پر منحصر ہے۔", "خوشگوار، میٹھی گفتگو، خاندانی محبت اور عوام، خوراک، مائعات یا تجارت سے فائدہ۔ آمدنی ذہنی کیفیت کے ساتھ اتار چڑھاؤ کا شکار ہو سکتی ہے۔", "تخیلاتی گفتگو، سفر کا شوق اور بہن بھائیوں سے محبت بھرا رشتہ؛ تحریر، میڈیا یا مختصر سفر میں کامیابی۔ موڈ کی تبدیلی کوششوں کو بکھیر سکتی ہے۔", "چاند کے بہترین خانوں میں سے ایک (دِگ بل): خوشحال گھر، آرام، گاڑیاں، والدہ سے قریبی رشتہ اور ذہنی سکون۔", "جذباتی ذہانت، تخلیقی صلاحیت اور اولاد سے محبت (اکثر بیٹیوں سے)؛ عوام یا مشاورتی کردار سے فائدہ۔ رومانوی معاملات میں حد سے زیادہ حساسیت سے بچیں۔", "خیال رکھنے والی، خدمت گزار طبیعت، صحت کی دیکھ بھال یا عوامی خدمت کے لیے موزوں؛ ہاضمے اور معدے کا خیال رکھیں، جذباتی دباؤ صحت پر اثر ڈال سکتا ہے۔", "جذباتی، دلکش ساتھی اور رفاقت کی گہری خواہش؛ عوامی معاملات میں کامیابی۔ ساتھی کے موڈ یا تبدیلی پر صبر کی ضرورت ہے۔", "گہرا، وجدانی اور رازدار ذہن؛ مخفی علوم میں دلچسپی اور ممکنہ وراثت۔ جذباتی اتار چڑھاؤ اور آنکھوں اور جسم کے سیالات کا خیال رکھیں۔", "عقیدت مند، مقبول اور خوش قسمت طبیعت، زیارت اور تعلیم کا شوق، اچھی اولاد اور والدہ کی حمایت۔ بیرون ملک سفر کا امکان ہے۔", "عوامی مقبولیت، کاروبار، مہمان نوازی، عوام سے متعلق یا خدمتی پیشوں میں کامیابی؛ کیریئر میں کئی تبدیلیاں۔ ساکھ چاند کی طاقت پر منحصر ہے۔", "بہت سے دوست (اکثر خواتین)، خواہشات کی تکمیل اور عوام و روابط سے مسلسل فائدہ۔ آمدنی میں اتار چڑھاؤ ہو سکتا ہے مگر وقت کے ساتھ بڑھتی ہے۔", "نجی، تخیلاتی باطنی زندگی، بیرونی مقامات کی طرف کشش، خیرات اور روحانی گوشہ نشینی۔ نیند، اخراجات اور جذباتی تنہائی کا خیال رکھیں۔"], "Mars": ["توانائی، ہمت اور بہادر، فعال شخصیت؛ جسمانی یا فنی شعبوں میں فطری قیادت۔ بے صبری، غصے اور سر پر معمولی چوٹ یا نشان سے بچیں۔ (منگل دوش میں شمار ہوتا ہے۔)", "کھری، زوردار گفتگو اور محنت، زمین یا فنی کام سے کمائی۔ خاندان میں جھگڑے اور بے دھڑک خرچ سے احتیاط ضروری ہے۔ (جنوبی ہند کے طریقہ کار میں منگل دوش میں شمار ہوتا ہے۔)", "مریخ کے بہترین خانوں میں سے ایک: زبردست ہمت، پہل کاری اور اپنی محنت سے کامیابی؛ کھیل، فوج، پولیس یا انجینئرنگ میں اچھا۔ بہن بھائیوں سے تعلقات میں مقابلے بازی ہو سکتی ہے۔", "محنت سے جائیداد، زمین اور گاڑیاں؛ اپنے گھر کی شدید خواہش۔ گھر کا سکون اور والدہ کی صحت کا خیال رکھیں؛ گھریلو جھگڑوں سے بچیں۔ (منگل دوش میں شمار ہوتا ہے۔)", "تیز، حکمت عملی پر مبنی ذہانت اور مقابلے کا تخلیقی جذبہ؛ کھیل یا ٹیکنالوجی میں دلچسپی۔ اولاد کچھ مشکل سے ہو سکتی ہے؛ لاپرواہ سٹے بازی سے گریز کریں۔", "مخالفین کو شکست دینے اور مقابلوں یا قانونی معاملات میں جیت کے لیے بہترین؛ ملازمت، سرجری، پولیس یا فوج میں کامیابی۔ بلڈ پریشر اور ورم کا خیال رکھیں۔", "پرجوش، توانا ساتھی اور شراکت داری و کاروبار میں دلیرانہ انداز۔ شادی میں رگڑ یا غلبے کا خیال رکھیں؛ صبر ضروری ہے۔ (منگل دوش میں شمار ہوتا ہے۔)", "تحقیق، سرجری، مخفی علوم یا بحرانی کام میں دلچسپی؛ ممکنہ وراثت یا اچانک فائدہ۔ حادثات، آپریشنز اور مشترکہ رقم پر تنازعات سے بچیں۔ (منگل دوش میں شمار ہوتا ہے۔)", "فعال، اصولی طبیعت جو عقائد کے لیے لڑتی ہے؛ زمین، تجارت یا سفر سے فائدہ۔ والد یا اساتذہ سے اختلافات ممکن ہیں؛ ہٹ دھرمی سے گریز کریں۔", "کیریئر کے لیے بہترین (دِگ بل): انجینئرنگ، فوج، کھیل، سرجری یا انتظام میں توانائی، کمان اور کامیابی؛ ادارے قائم کر سکتا ہے۔ اعلیٰ حکام سے تنازعات سے بچیں۔", "محنت، جائیداد اور بااثر دوستوں سے مضبوط فائدہ؛ خواہشات سخت محنت سے پوری ہوتی ہیں۔ بڑے بہن بھائی یا دوست مقابلہ بازی کر سکتے ہیں۔", "توانائی بیرونی معاملات، ہسپتالوں، روحانی مشق یا مخفی کام پر خرچ ہوتی ہے؛ اخراجات زیادہ ہو سکتے ہیں۔ نیند، غصے اور پوشیدہ دشمنوں کا خیال رکھیں۔ (منگل دوش میں شمار ہوتا ہے۔)"], "Mercury": ["ذہین، حاضر جواب، نوجوان اور بات چیت کرنے والی شخصیت؛ اچھی سیکھنے کی صلاحیت اور تجارت، تحریر یا تقریر کی صلاحیت۔ بے چین یا گھبرایا ہوا ہو سکتا ہے۔", "فصیح، قائل کرنے والی گفتگو، زبانوں، حساب کتاب اور تجارت میں مہارت؛ ذہانت سے کمائی۔ چالاکی کو بحث میں بدلنے سے بچیں۔", "بہترین رابطہ کاری، تحریر، میڈیا، تجارت اور مختصر سفر؛ حکمت عملی اور تیز فہمی۔ بہن بھائیوں سے تعلقات عموماً ذہین اور خوش گوار ہوتے ہیں۔", "تعلیم، پڑھا لکھا گھرانہ، جائیداد، گاڑیوں یا ادبی کام میں کامیابی اور خیال رکھنے والی والدہ۔ گھر میں ذہنی بے چینی لا سکتا ہے۔", "تیز ذہانت، ریاضی، تجزیے اور مشاورتی یا انتظامی کرداروں میں مہارت؛ اچھے طالب علم۔ اولاد ذہین اور باتونی ہو سکتی ہے۔", "تجزیاتی، باریک بینی والا کام: حساب کتاب، قانون، صحت یا ملازمت؛ مخالفین کو دلائل میں مات دینے کی صلاحیت۔ اعصابی تناؤ، جلد اور ہاضمے کی حساسیت کا خیال رکھیں۔", "نوجوان، ذہین ساتھی اور تجارت، مذاکرات اور کاروباری شراکت داری میں کامیابی۔ اچھی گفتگو رشتوں کے لیے فائدہ مند ہے۔", "تحقیق، چھان بین، مخفی علوم کا مطالعہ اور طویل عمر؛ وراثت یا انشورنس سے ممکنہ فائدہ۔ فکر اور رازداری میں توازن کی ضرورت ہے۔", "اعلیٰ تعلیم، فلسفہ، قانون، اشاعت اور تدریس؛ متعدد دلچسپیاں اور تخلیقی، سائنسی صلاحیت۔ عقیدے کو ضرورت سے زیادہ عقلی بنا سکتا ہے۔", "رابطہ کاری، تجارت، آئی ٹی، حسابات، تحریر یا تدریس کے ذریعے کیریئر؛ کام میں ذہین اور خوش قسمت — عطارد پہلے خانے میں دِگ بل حاصل کرتا ہے، مگر یہاں بھی اچھا کام کرتا ہے۔", "تجارت، روابط، ریاضی اور رابطہ کاری سے فائدہ؛ بہت سے دوست اور خواہشات کی تکمیل۔ آمدنی کئی ذرائع سے آ سکتی ہے۔", "غور و فکر کرنے والا، فلسفیانہ ذہن، بیرونی زبانوں، تحقیق یا روحانیت میں دلچسپی۔ فکر، تعلیم پر اخراجات اور رابطے کی کمی کا خیال رکھیں۔"], "Jupiter": ["مشتری کے بہترین خانوں میں سے ایک (دِگ بل): حکمت، وقار، اچھا کردار اور پوری کنڈلی پر حفاظتی اثر؛ رہنما یا استاد کے طور پر احترام۔ وزن بڑھنے اور حد سے زیادہ رجائیت سے بچیں۔", "دولت، مہذب خاندان، روانی اور سچائی سے بھری گفتگو اور تدریس، قانون یا مالیات میں کامیابی۔ وقت کے ساتھ دولت جمع ہوتی رہتی ہے۔", "رابطہ کاری اور تحریر میں حکمت؛ بہن بھائیوں سے اچھے تعلقات۔ کوششیں سست ہو سکتی ہیں یا مشتری کی سخاوت یہاں کم ہو سکتی ہے؛ مسلسل محنت درکار ہے۔", "خوشحال، آرام دہ گھر، اچھی تعلیم، جائیداد اور گاڑیاں، اور خیال رکھنے والی والدہ؛ باطنی اطمینان۔ مشتری کی مضبوط زاویائی پوزیشنوں میں سے ایک۔", "ذہانت، اولاد، تعلیم، مشاورت اور روحانی مشق کے لیے بہترین؛ اچھی سمجھ بوجھ اور معزز مقام۔", "حکمت اور اخلاق کے ذریعے فتح، ملازمت، قانون، طب یا مشاورت کے لیے موزوں۔ روایتی کتب اسے یہاں کمزور شمار کرتی ہیں؛ قرض، وزن اور جگر کی صحت کا خیال رکھیں۔", "دانا، نیک اور اکثر تعلیم یافتہ ساتھی؛ شراکت داری، قانون اور مشاورت میں کامیابی۔ مشتری یہاں سے طالع پر نظر ڈالتا ہے، جو صحت اور کردار کو سہارا دیتا ہے۔", "طویل عمر، روحانی اور مخفی علم میں دلچسپی، ممکنہ وراثت۔ روایتی کتب اسے کم آرام دہ شمار کرتی ہیں؛ نتائج رکاوٹوں کے بعد ملتے ہیں۔", "سب سے خوش قسمت پوزیشنوں میں سے ایک: دھرم، عقیدہ، اچھے اساتذہ، اولاد، سخاوت اور اعلیٰ تعلیم، قانون، مذہب یا سفر کے ذریعے قسمت۔", "تدریس، قانون، مالیات، مشاورت یا انتظام میں باعزت کیریئر؛ معزز، اخلاقی اور ادارے قائم کرنے کی صلاحیت۔ ترقیاں مسلسل ملتی رہتی ہیں۔", "خاطر خواہ فائدہ، خواہشات کی تکمیل، علم والے اور بااثر دوست؛ عمر کے ساتھ آمدنی بڑھتی ہے۔ خوشحالی کے لیے انتہائی فائدہ مند پوزیشن۔", "سخاوت، خیرات، روحانی ترقی اور موکش (نجات) میں دلچسپی؛ نیک کاموں اور بیرون ملک سفر پر اخراجات۔ مالی بچت کا خیال رکھنے کی ضرورت ہو سکتی ہے۔"], "Venus": ["دلکشی، خوبصورتی، فنکارانہ ذوق اور خوشگوار، ملنسار طبیعت؛ آسائشیں اور تعلقات میں اچھی قسمت۔ عیش پرستی اور نمائش سے بچیں۔", "دولت، خوشحال خاندان، میٹھی گفتگو اور فنون، آسائش، خوبصورتی یا مالیات سے کمائی؛ اچھے کھانے کا شوق۔ زیادہ خرچ سے بچیں۔", "فنکارانہ اور تخلیقی گفتگو، موسیقی اور میڈیا کا شوق؛ محبت کرنے والے بہن بھائی۔ ہمت نرم ہو سکتی ہے؛ کامیابی دلکشی اور مہارت سے ملتی ہے۔", "زہرہ کے بہترین خانوں میں سے ایک: خوبصورت گھر، گاڑیاں، آسائشیں، محبت کرنے والی والدہ اور گھریلو خوشی؛ فنون میں اچھی تعلیم۔", "تخلیقی صلاحیت، رومانس، فنکارانہ ذہانت اور اولاد سے خوشی؛ تفریح، ڈیزائن یا احتیاط کے ساتھ سٹے بازی میں کامیابی۔", "روایتی کتب یہاں زہرہ کو کمزور شمار کرتی ہیں: رشتوں کو رکاوٹوں کا سامنا ہو سکتا ہے یا وہ کام کے ذریعے ملتے ہیں؛ خوبصورتی، صحت یا مہمان نوازی کی ملازمت کے لیے موزوں۔ شکر اور عیش پرستی سے بچیں۔", "شادی کا فطری خانہ: دلکش، محبت کرنے والا ساتھی اور شراکت داری، کاروبار اور عوامی معاملات میں خوشی۔ رومانس اور ذمہ داری میں توازن رکھیں۔", "شریک حیات، وراثت یا مشترکہ وسائل سے فائدہ؛ مخفی لذتوں یا مخفی علوم میں دلچسپی۔ تولیدی صحت اور خفیہ تعلقات کا خیال رکھیں۔", "فنون، مہذب شریک حیات یا بیرونی روابط کے ذریعے قسمت؛ فیاض، شائستہ اور وفادار۔ تفریح یا تعلیم کے لیے سفر۔", "فنون، فیشن، ڈیزائن، میڈیا، مہمان نوازی، مالیات یا سفارت کاری میں کیریئر؛ عوام میں دلکشی اور مقبولیت۔ خواتین یا شراکت داروں کے ذریعے کامیابی۔", "فنون، آسائش، شراکت داروں اور بااثر دوستوں سے فائدہ؛ خواہشات کی تکمیل اور آرام دہ آمدنی۔", "روایتی طور پر زہرہ کے لیے پسندیدہ مقام: بستر اور آرام کی آسائشیں، بیرون ملک سفر، خوبصورتی کے ذریعے روحانی عقیدت۔ زیادہ خرچ اور خفیہ تعلقات سے بچیں۔"], "Saturn": ["سنجیدہ، پختہ، محنتی اور صابر طبیعت؛ کامیابی آہستہ آتی ہے مگر قائم رہتی ہے۔ مایوسی، تنہائی اور دیرینہ صحت کے مسائل سے بچیں؛ اگر زحل اپنے یا شرف کے برج میں ہو تو مضبوط ہوتا ہے۔", "نظم و ضبط اور بچت سے آہستہ آہستہ دولت کی تعمیر؛ ناپی تلی، محتاط گفتگو۔ خاندانی ذمہ داریاں، تعلیم میں تاخیر اور بینائی کا خیال رکھیں۔", "زحل کے بہترین خانوں میں سے ایک: استقامت، برداشت کے ذریعے ہمت اور مسلسل محنت کے بعد کامیابی؛ طویل مدتی منصوبہ بندی۔ بہن بھائیوں سے تعلقات دور ہو سکتے ہیں۔", "گھر میں ذمہ داریاں، جائیداد یا گاڑیوں میں تاخیر اور والدہ سے سنجیدہ رشتہ؛ عمر کے ساتھ ذہنی سکون بڑھتا ہے۔ کامیابی جائے پیدائش سے دور مل سکتی ہے۔", "سنجیدہ، عملی ذہانت اور تعلیم میں نظم و ضبط؛ اولاد میں تاخیر ہو سکتی ہے یا کم ہو، اور سٹے بازی سے گریز کرنا چاہیے۔", "استقامت کے ذریعے مخالفین کو شکست دینے کے لیے بہترین؛ ملازمت، محنت مزدوری، قانون یا صحت کی دیکھ بھال کے لیے موزوں۔ صحت کے مسائل دیرینہ ہو سکتے ہیں مگر نظم و ضبط سے قابو میں رہتے ہیں۔", "پختہ، وفادار یا عمر میں بڑا ساتھی؛ شادی میں تاخیر ہو سکتی ہے مگر مستحکم ہوتی ہے۔ طویل مدتی کاروباری شراکت داری میں کامیابی (زحل کے لیے دِگ بل)۔", "طویل عمر، تحقیق اور مخفی موضوعات میں دلچسپی؛ آہستہ مگر پائیدار تبدیلی۔ وراثت میں تاخیر اور دیرینہ بیماریوں پر صبر کی ضرورت ہے۔", "منظم عقیدہ اور روایت کا احترام؛ قسمت زندگی میں بعد میں محنت سے آتی ہے۔ والد یا اساتذہ سے اختلافات ممکن ہیں۔", "کیریئر کے لیے انتہائی مضبوط: سخت محنت، ذمہ داری، وقت کے ساتھ حاصل ہونے والا اختیار، انتظامیہ، قانون، انجینئرنگ یا بڑے اداروں میں کامیابی (اگر اپنے یا شرف کے برج میں ہو تو ششا یوگ)۔", "استقامت سے مسلسل، پائیدار فائدہ اور دولت؛ بااثر، عمر میں بڑے یا اعلیٰ دوست۔ عمر کے ساتھ آمدنی بڑھتی ہے۔", "اخراجات، بیرون ملک رہائش، ہسپتالوں، آشرموں یا تنہا مقامات پر کام؛ روحانی نظم و ضبط۔ نیند، پاؤں اور پوشیدہ نقصانات کا خیال رکھیں۔"], "Rahu": ["غیر روایتی، پرعزم اور پرکشش شخصیت، نئے خیالات، ٹیکنالوجی یا بیرونی ثقافت کی طرف مائل۔ شناخت کے حوالے سے الجھن اور مشکل سے تشخیص ہونے والی صحت کی خرابیوں سے بچیں۔", "آمدنی کے غیر معمولی ذرائع، بیرونی زبانوں یا میڈیا میں مہارت؛ دلیرانہ گفتگو۔ مبالغہ آرائی، خاندانی جھگڑوں اور بے قاعدہ کھانے پینے سے بچیں۔", "راہو کے بہترین خانوں میں سے ایک: ہمت، عزم، میڈیا، ٹیکنالوجی، مارکیٹنگ یا رابطہ کاری میں کامیابی، اور دلیرانہ پہل کاری۔", "جائے پیدائش سے دور یا بیرون ملک آباد ہونا، غیر معمولی گھریلو زندگی؛ جائیداد یا گاڑیوں میں دلچسپی۔ ذہنی سکون اور والدہ کی صحت کا خیال رکھیں۔", "موجد، غیر روایتی ذہانت؛ سٹے بازی، ٹیکنالوجی یا تحقیق میں دلچسپی۔ اولاد غیر معمولی طریقے سے یا تاخیر سے ہو سکتی ہے؛ خطرناک شرط بازی سے بچیں۔", "راہو کی بہترین پوزیشن: مخالفین پر فتح، مقابلوں، ملازمت، طب یا قانون میں غیر روایتی ذرائع سے کامیابی۔", "غیر روایتی یا بیرونی ساتھی اور بیرونی روابط والا کاروبار؛ شراکت داری میں عزم۔ رشتوں میں وضاحت اور اعتماد کا خیال رکھیں۔", "تحقیق اور مخفی علوم میں گہری دلچسپی؛ اچانک فائدہ یا نقصان اور غیر متوقع واقعات۔ خطرناک منصوبوں اور پوشیدہ صحت کے مسائل سے احتیاط برتیں۔", "غیر روایتی یا بیرونی عقائد اور اساتذہ، بیرون ملک سفر؛ اچھے تعلق میں راج یوگ بن سکتا ہے۔ عقیدے پر بزرگوں سے تنازع سے بچیں۔", "پرعزم، غیر روایتی کیریئر، ٹیکنالوجی، بیرونی اداروں یا میڈیا میں کامیابی، اور رتبے کی شدید خواہش۔ شارٹ کٹ سے ساکھ کو بچائیں۔", "عموماً راہو کے سب سے فائدہ مند مقامات میں سے ایک: بڑا فائدہ، طاقتور دوست اور خواہشات کی تکمیل، اکثر ٹیکنالوجی یا بیرونی روابط کے ذریعے۔", "بیرون ملک رہائش، روحانی یا مخفی علوم کی جستجو اور غیر معمولی اخراجات؛ نیند کی خرابی اور پوشیدہ نقصانات کا خیال رکھیں۔"], "Ketu": ["لاتعلق، روحانی اور وجدانی شخصیت جس میں گہری بصیرت ہو؛ شناخت کے حوالے سے غیر یقینی محسوس ہو سکتی ہے۔ مجموعی توانائی کا خیال رکھیں۔", "دولت یا خاندان سے لاتعلقی، غیر معمولی گفتگو یا خوراک؛ روحانی تعلیم۔ بچت اور خاندانی ہم آہنگی پر توجہ درکار ہے۔", "ہمت، مضبوط وجدان اور آزادانہ محنت سے کامیابی؛ تصوف یا غیر معمولی مہارتوں میں دلچسپی۔ بہن بھائیوں سے تعلقات دور ہو سکتے ہیں۔", "گھر یا جائے پیدائش سے لاتعلقی، رہائش میں بار بار تبدیلی؛ سکون کی باطنی تلاش۔ والدہ کی صحت کا خیال رکھیں۔", "وجدانی، تحقیق پسند ذہانت اور پچھلے جنم کا روحانی نیک عمل؛ اولاد یا رومانس میں چیلنجز یا تاخیر آ سکتی ہے۔", "کیتو کے مضبوط خانوں میں سے ایک: دشمنوں پر فتح، تیز فطری حس، شفا، تحقیق یا ملازمت میں کامیابی۔", "روحانی یا غیر معمولی شراکت داری؛ شادی اور کاروبار میں لاتعلقی یا غلط فہمیوں کا خیال رکھیں۔", "مخفی علوم، تحقیق اور پوشیدہ معاملات میں گہری دلچسپی؛ اچانک تبدیلیاں۔ حادثات اور پوشیدہ بیماریوں سے بچیں۔", "غیر روایتی عقیدہ، رسومات سے لاتعلقی اور گہری روحانی بصیرت؛ اساتذہ یا والد سے اختلافات ممکن ہیں۔", "کیریئر میں اچانک تبدیلیاں، وجدان یا روحانی دلچسپیوں سے رہنمائی پانے والا کام؛ تحقیق، ٹیکنالوجی یا شفا۔ اچانک فیصلوں سے بچیں۔", "فائدہ جو آتا جاتا رہتا ہے، خواہشات سے لاتعلقی، حاضر جواب اور ذہین؛ چند معنی خیز دوستیاں۔", "روایتی طور پر موکش (نجات) سے جڑا ہوا: روحانی نجات، بیرونی ممالک اور گوشہ نشینی؛ روحانی مقاصد پر اخراجات۔"]}, "hi": {"Sun": ["आत्मबल, नेतृत्व क्षमता और गरिमामयी उपस्थिति; अच्छी जीवनी शक्ति और सम्मान पाने की इच्छा। अहंकार और तीखे स्वभाव से सावधान रहें, तथा सिर, आँखों और हृदय का ध्यान रखें।", "अधिकार, सरकार या पिता पक्ष से आय, तथा आत्मविश्वासी और प्रभावशाली वाणी। परिवार में कठोर शब्दों और रुतबा बनाए रखने के खर्च से सावधान रहें।", "साहस, पहल क्षमता और स्वयं के प्रयासों से सफलता; संचार, लेखन या छोटी यात्राओं से यश। छोटे भाई-बहनों से संबंधों में प्रतिस्पर्धा हो सकती है।", "संपत्ति और सम्मानजनक घर की महत्वाकांक्षा, जन्मस्थान से दूर सफलता। अहंकार के टकराव से घर की शांति भंग हो सकती है; हृदय और माता के स्वास्थ्य का ध्यान रखें।", "तीक्ष्ण बुद्धि, रचनात्मक एवं सलाहकार क्षमता, राजनीति या सट्टे में रुचि। संतान कम या देर से हो सकती है; जल्दबाज़ी में सट्टेबाज़ी से बचें।", "सूर्य के लिए सर्वश्रेष्ठ भावों में से एक: शत्रुओं पर विजय, सेवा, प्रशासन और प्रतिस्पर्धा में सफलता, बीमारियों के प्रति अच्छी प्रतिरोधक क्षमता। अधिक कार्यभार और कार्यस्थल पर टकराव से सावधान रहें।", "दृढ़ इच्छाशक्ति या प्रतिष्ठा के प्रति सजग साथी के साथ साझेदारी और विवाह; जनसंपर्क से लाभ। रिश्तों में अहंकार विवाह में देरी या तनाव का कारण बन सकता है।", "गुप्त विषयों, शोध और विरासत में रुचि; स्थिति में अचानक परिवर्तन। आँखों और सामान्य जीवनी शक्ति का ध्यान रखें; अनावश्यक जोखिम से बचें।", "सौभाग्य, धर्म तथा गुरुजनों और पिता के प्रति सम्मान; उच्च शिक्षा, कानून या धर्म से लाभ। व्यक्ति को आत्मधर्मी बना सकता है या पिता से दूरी उत्पन्न कर सकता है।", "करियर के लिए उत्कृष्ट: अधिकार, यश, सरकारी या नेतृत्व के पद और सार्वजनिक पहचान — यहाँ सूर्य को दिग्बल प्राप्त होता है। कार्यस्थल पर अहंकार से बचें।", "बिना अधिक प्रयास के लाभ, प्रभावशाली मित्र और महत्वाकांक्षाओं की पूर्ति; सरकार या वरिष्ठ व्यक्तियों से आय। मित्रता प्रतिष्ठा-आधारित हो सकती है।", "आध्यात्मिकता, विदेश और एकांत में रुचि; प्रतिष्ठा, यात्रा या दान पर खर्च। आत्मविश्वास और नेत्र-ज्योति का ध्यान रखें; पहचान देर से मिल सकती है।"], "Moon": ["आकर्षक, संवेदनशील और मिलनसार स्वभाव, लोगों में लोकप्रिय और मनोदशा में परिवर्तनशील। भावनात्मक संतुलन चंद्रमा की स्थिति (शुक्ल या कृष्ण पक्ष) पर निर्भर करता है।", "मधुर और सुखद वाणी, पारिवारिक स्नेह तथा जनता, खाद्य पदार्थों, तरल पदार्थों या व्यापार से लाभ। मन की स्थिति के साथ आय में उतार-चढ़ाव हो सकता है।", "कल्पनाशील संवाद, यात्रा का शौक तथा भाई-बहनों से स्नेहपूर्ण संबंध; लेखन, मीडिया या छोटी यात्राओं में सफलता। मनोदशा में उतार-चढ़ाव प्रयासों को बिखेर सकता है।", "चंद्रमा के लिए सर्वश्रेष्ठ भावों में से एक (दिग्बल): सुखी घर, सुख-सुविधाएँ, वाहन, माता से गहरा संबंध और मानसिक शांति।", "भावनात्मक समझ, रचनात्मकता तथा संतान (प्रायः पुत्रियों) के प्रति स्नेह; जनता या सलाहकार भूमिकाओं से लाभ। प्रेम संबंधों में अति-संवेदनशीलता से बचें।", "देखभाल करने वाला, सेवाभावी स्वभाव, स्वास्थ्य सेवा या लोकसेवा के लिए उपयुक्त; पाचन और पेट का ध्यान रखें, भावनात्मक तनाव स्वास्थ्य को प्रभावित कर सकता है।", "भावुक, आकर्षक साथी तथा साहचर्य की गहरी आवश्यकता; जनसंपर्क में सफलता। साथी की मनोदशा या परिवर्तनशीलता के लिए धैर्य आवश्यक है।", "गहरा, सहज-बोध वाला और गोपनीय मन; गूढ़ विद्या में रुचि और संभावित विरासत। भावनात्मक उतार-चढ़ाव तथा आँखों और शरीर के तरल पदार्थों का ध्यान रखें।", "धार्मिक, लोकप्रिय और भाग्यशाली स्वभाव, तीर्थयात्रा और अध्ययन का शौक, अच्छी संतान तथा माता का सहयोग। विदेश यात्रा की संभावना है।", "जनता में लोकप्रियता, व्यापार, आतिथ्य, जनसंपर्क या सेवा-संबंधी व्यवसायों में सफलता; कई बदलावों वाला करियर पथ। प्रतिष्ठा चंद्रमा की स्थिति पर निर्भर करती है।", "अनेक मित्र (प्रायः महिलाएँ), इच्छाओं की पूर्ति तथा जनता और संपर्कों से निरंतर लाभ। आय में उतार-चढ़ाव हो सकता है परंतु समय के साथ बढ़ने की प्रवृत्ति रहती है।", "निजी, कल्पनाशील आंतरिक जीवन, विदेशी स्थानों, दान और आध्यात्मिक एकांतवास के प्रति आकर्षण। नींद, खर्च और भावनात्मक अलगाव का ध्यान रखें।"], "Mars": ["ऊर्जा, साहस तथा निडर, सक्रिय व्यक्तित्व; शारीरिक या तकनीकी क्षेत्रों में स्वाभाविक नेतृत्व। अधीरता, क्रोध तथा सिर पर छोटी चोट या निशान से सावधान रहें। (मांगलिक दोष के लिए गणना होती है।)", "स्पष्ट, प्रबल वाणी तथा परिश्रम, भूमि या तकनीकी कार्य से अर्जित धन। परिवार में झगड़े और आवेगपूर्ण खर्च मुख्य सावधानियाँ हैं। (दक्षिण भारतीय पद्धति में मांगलिक दोष के लिए गणना होती है।)", "मंगल के लिए सर्वश्रेष्ठ भावों में से एक: महान साहस, पहल क्षमता और स्वयं के प्रयासों से सफलता; खेल, सेना, पुलिस या इंजीनियरिंग में अच्छा। भाई-बहनों से संबंधों में प्रतिस्पर्धा हो सकती है।", "परिश्रम से संपत्ति, भूमि और वाहन; अपने घर की तीव्र इच्छा। घर की शांति और माता के स्वास्थ्य का ध्यान रखें; घरेलू विवादों से बचें। (मांगलिक दोष के लिए गणना होती है।)", "तीक्ष्ण, रणनीतिक बुद्धि तथा प्रतिस्पर्धी रचनात्मक ऊर्जा; खेल या तकनीक में रुचि। संतान प्राप्ति में कुछ कठिनाई हो सकती है; लापरवाह सट्टेबाज़ी से बचें।", "शत्रुओं को परास्त करने तथा प्रतियोगिताओं या कानूनी मामलों में विजय के लिए उत्कृष्ट; सेवा, शल्य चिकित्सा, पुलिस या सेना में सफलता। रक्तचाप और सूजन से सावधान रहें।", "जोशीला, ऊर्जावान साथी तथा साझेदारी और व्यवसाय के प्रति निडर दृष्टिकोण। विवाह में टकराव या प्रभुत्व का ध्यान रखें; धैर्य आवश्यक है। (मांगलिक दोष के लिए गणना होती है।)", "शोध, शल्य चिकित्सा, गूढ़ विद्या या संकटकालीन कार्य में रुचि; संभावित विरासत या अचानक लाभ। दुर्घटनाओं, ऑपरेशन तथा साझा धन पर विवादों से सावधान रहें। (मांगलिक दोष के लिए गणना होती है।)", "सक्रिय, सिद्धांतवादी स्वभाव जो अपनी मान्यताओं के लिए संघर्ष करता है; भूमि, व्यापार या यात्रा से लाभ। पिता या गुरुजनों से मतभेद संभव हैं; हठधर्मिता से बचें।", "करियर के लिए उत्कृष्ट (दिग्बल): इंजीनियरिंग, सेना, खेल, शल्य चिकित्सा या प्रबंधन में ऊर्जा, कमान और उपलब्धि; संस्थाओं की स्थापना कर सकते हैं। अधिकारियों से टकराव से सावधान रहें।", "परिश्रम, संपत्ति और प्रभावशाली मित्रों से अच्छा लाभ; कड़ी मेहनत से महत्वाकांक्षाएँ पूरी होती हैं। बड़े भाई-बहन या मित्रों में प्रतिस्पर्धा हो सकती है।", "विदेशी मामलों, अस्पतालों, आध्यात्मिक साधना या गुप्त कार्य में ऊर्जा व्यय; खर्च अधिक हो सकता है। नींद, क्रोध और छिपे शत्रुओं का ध्यान रखें। (मांगलिक दोष के लिए गणना होती है।)"], "Mercury": ["चतुर, विनोदी, युवा और मिलनसार व्यक्तित्व; अच्छी सीखने की क्षमता तथा व्यापार, लेखन या वाक्पटुता में प्रतिभा। बेचैन या घबराया हुआ हो सकता है।", "स्पष्ट, प्रभावशाली वाणी, भाषाओं, हिसाब-किताब और व्यापार में कुशलता; बुद्धि से आय। चतुराई के तर्क-वितर्क में बदलने से सावधान रहें।", "उत्कृष्ट संवाद, लेखन, मीडिया, वाणिज्य और छोटी यात्राएँ; व्यवहार कुशल और तीव्र सोच। भाई-बहनों से संबंध प्रायः बौद्धिक और जीवंत होते हैं।", "शिक्षा, पढ़े-लिखे वातावरण वाला घर, संपत्ति, वाहन या साहित्यिक कार्य में सफलता तथा स्नेही माता। घर में मानसिक बेचैनी ला सकता है।", "तीक्ष्ण बुद्धि, गणित, विश्लेषण तथा सलाहकार या प्रशासनिक भूमिकाओं में कुशलता; अच्छे विद्यार्थी। संतान बुद्धिमान और मिलनसार हो सकती है।", "विश्लेषणात्मक, बारीकी वाला कार्य: हिसाब-किताब, कानून, स्वास्थ्य या सेवा; विरोधियों को तर्क में परास्त करने में सक्षम। मानसिक तनाव, त्वचा और पाचन की संवेदनशीलता से सावधान रहें।", "युवा, बुद्धिमान साथी तथा व्यापार, बातचीत और व्यावसायिक साझेदारियों में सफलता। अच्छे संवाद से रिश्तों को लाभ होता है।", "शोध, जाँच-पड़ताल, गूढ़ विद्या का अध्ययन तथा दीर्घायु; विरासत या बीमा से संभावित लाभ। चिंता और गोपनीय सोच में संतुलन आवश्यक है।", "उच्च शिक्षा, दर्शन, कानून, प्रकाशन और अध्यापन; अनेक रुचियाँ तथा रचनात्मक, वैज्ञानिक क्षमता। धर्म को अत्यधिक तार्किक बना सकता है।", "संवाद, व्यापार, आईटी, लेखा, लेखन या अध्यापन के माध्यम से करियर; कार्य में बुद्धिमान और भाग्यशाली — बुध को प्रथम भाव में दिग्बल प्राप्त होता है, परंतु यहाँ भी अच्छा फल देता है।", "व्यापार, संपर्कों, गणित और संवाद से लाभ; अनेक मित्र और पूर्ण इच्छाएँ। आय कई स्रोतों से आ सकती है।", "चिंतनशील, दार्शनिक मन, विदेशी भाषाओं, शोध या आध्यात्मिकता में रुचि। चिंता, अध्ययन पर खर्च और संवाद की कमी का ध्यान रखें।"], "Jupiter": ["गुरु के लिए सर्वश्रेष्ठ भावों में से एक (दिग्बल): ज्ञान, गरिमा, अच्छा चरित्र तथा संपूर्ण कुंडली पर रक्षात्मक प्रभाव; मार्गदर्शक या गुरु के रूप में सम्मान। वज़न बढ़ने और अति-आशावाद से सावधान रहें।", "धन, संस्कारी परिवार, सहज और सत्यवादी वाणी तथा अध्यापन, कानून या वित्त में सफलता। समय के साथ धन संचित होने की प्रवृत्ति रहती है।", "संवाद और लेखन में समझदारी; भाई-बहनों से अच्छे संबंध। प्रयास धीमे हो सकते हैं या यहाँ गुरु की उदारता कम हो जाती है; निरंतर प्रयास आवश्यक है।", "सुखी, आरामदायक घर, अच्छी शिक्षा, संपत्ति और वाहन तथा स्नेही माता; आंतरिक संतोष। गुरु की मज़बूत केंद्र स्थितियों में से एक।", "बुद्धि, संतान, शिक्षा, सलाह और आध्यात्मिक साधना के लिए उत्कृष्ट; अच्छा निर्णय और सम्मानित स्थिति।", "ज्ञान और नैतिकता से विजय, सेवा, कानून, चिकित्सा या परामर्श के लिए उपयुक्त। शास्त्रीय ग्रंथों में इसे यहाँ कमज़ोर माना गया है; ऋण, वज़न और यकृत के स्वास्थ्य से सावधान रहें।", "बुद्धिमान, सदाचारी और प्रायः शिक्षित साथी; साझेदारी, कानून और परामर्श में सफलता। यहाँ से गुरु लग्न को देखता है, जो स्वास्थ्य और चरित्र को सहारा देता है।", "दीर्घायु, आध्यात्मिक और गूढ़ ज्ञान में रुचि, संभावित विरासत। शास्त्रीय ग्रंथों में इसे कम अनुकूल माना गया है; परिणाम बाधाओं के बाद मिलते हैं।", "सबसे शुभ स्थितियों में से एक: धर्म, श्रद्धा, अच्छे गुरु, संतान, उदारता तथा उच्च शिक्षा, कानून, धर्म या यात्रा से सौभाग्य।", "अध्यापन, कानून, वित्त, सलाह या प्रशासन में सम्मानजनक करियर; सम्मानित, नैतिक तथा संस्थाओं की स्थापना करने में सक्षम। पदोन्नति निरंतर मिलती रहती है।", "पर्याप्त लाभ, इच्छाओं की पूर्ति, विद्वान और प्रभावशाली मित्र; आयु के साथ आय बढ़ती है। समृद्धि के लिए अत्यंत लाभकारी स्थिति।", "उदारता, दान, आध्यात्मिक उन्नति तथा मोक्ष में रुचि; अच्छे कार्यों और विदेश यात्रा पर खर्च। भौतिक बचत का ध्यान रखने की आवश्यकता हो सकती है।"], "Venus": ["आकर्षण, सुंदरता, कलात्मक रुचि तथा सुखद, मिलनसार स्वभाव; सुख-सुविधाएँ और रिश्तों में सौभाग्य। भोग-विलास और घमंड से सावधान रहें।", "धन, सुखी परिवार, मधुर वाणी तथा कला, विलासिता, सौंदर्य या वित्त से आय; अच्छे भोजन का शौक। अधिक खर्च से बचें।", "कलात्मक और रचनात्मक संवाद, संगीत और मीडिया का शौक; स्नेही भाई-बहन। साहस कोमल हो सकता है; सफलता आकर्षण और कौशल से मिलती है।", "शुक्र के लिए सर्वश्रेष्ठ भावों में से एक: सुंदर घर, वाहन, सुख-सुविधाएँ, स्नेही माता और घरेलू सुख; कला में अच्छी शिक्षा।", "रचनात्मकता, प्रेम, कलात्मक बुद्धि तथा संतान से आनंद; मनोरंजन, डिज़ाइन या सावधानीपूर्वक सट्टे में सफलता।", "शास्त्रीय ग्रंथों में यहाँ शुक्र को कमज़ोर माना गया है: रिश्तों में बाधाएँ आ सकती हैं या वे कार्यस्थल से बनते हैं; सौंदर्य, स्वास्थ्य या आतिथ्य सेवा के लिए उपयुक्त। शर्करा और भोग-विलास से सावधान रहें।", "विवाह का स्वाभाविक भाव: आकर्षक, स्नेही साथी तथा साझेदारी, व्यवसाय और जनसंपर्क में आनंद। प्रेम और ज़िम्मेदारी में संतुलन रखें।", "जीवनसाथी, विरासत या साझा संसाधनों से लाभ; गुप्त सुखों या गूढ़ विद्या में रुचि। प्रजनन स्वास्थ्य और गुप्त संबंधों से सावधान रहें।", "कला, संस्कारी जीवनसाथी या विदेशी संपर्कों से सौभाग्य; उदार, परिष्कृत और समर्पित। आनंद या अध्ययन हेतु यात्रा।", "कला, फैशन, डिज़ाइन, मीडिया, आतिथ्य, वित्त या कूटनीति में करियर; जनता में आकर्षण और लोकप्रियता। महिलाओं या साझेदारों से सफलता।", "कला, विलासिता, साझेदारों और प्रभावशाली मित्रों से लाभ; इच्छाओं की पूर्ति और आरामदायक आय।", "शास्त्रीय रूप से शुक्र के लिए अनुकूल स्थान: शय्या सुख और विश्राम, विदेश यात्रा, सौंदर्य के माध्यम से आध्यात्मिक भक्ति। अधिक खर्च और गुप्त संबंधों से सावधान रहें।"], "Saturn": ["गंभीर, परिपक्व, परिश्रमी और धैर्यवान स्वभाव; सफलता धीरे-धीरे मिलती है परंतु स्थायी होती है। निराशावाद, अकेलापन और पुरानी स्वास्थ्य समस्याओं से सावधान रहें; यदि शनि स्वराशि या उच्च राशि में हो तो प्रबल।", "अनुशासन और बचत से धीरे-धीरे धन का निर्माण; संयमित, सतर्क वाणी। पारिवारिक ज़िम्मेदारियाँ, विलंबित शिक्षा और नेत्र-ज्योति का ध्यान रखें।", "शनि के लिए सर्वश्रेष्ठ भावों में से एक: दृढ़ता, सहनशीलता से साहस तथा निरंतर प्रयास के बाद सफलता; दीर्घकालिक योजना। भाई-बहनों से संबंध दूर हो सकते हैं।", "घर में ज़िम्मेदारियाँ, संपत्ति या वाहन में देरी तथा माता से गंभीर संबंध; आयु के साथ मानसिक शांति बढ़ती है। जन्मस्थान से दूर सफलता मिल सकती है।", "गंभीर, व्यावहारिक बुद्धि और अध्ययन में अनुशासन; संतान में देरी या कम संतान हो सकती है, सट्टेबाज़ी से बचना चाहिए।", "दृढ़ता से शत्रुओं को परास्त करने के लिए उत्कृष्ट; सेवा, श्रम, कानून या स्वास्थ्य सेवा के लिए उपयुक्त। स्वास्थ्य समस्याएँ पुरानी हो सकती हैं परंतु अनुशासन से नियंत्रित की जा सकती हैं।", "परिपक्व, वफादार या बड़ी आयु का साथी; विवाह में देरी हो सकती है परंतु यह स्थिर रहता है। दीर्घकालिक व्यावसायिक साझेदारियों में सफलता (शनि के लिए दिग्बल)।", "दीर्घायु, शोध और गुप्त विषयों में रुचि; धीमा परंतु स्थायी परिवर्तन। विरासत में देरी और पुरानी बीमारियों के लिए धैर्य आवश्यक है।", "अनुशासित श्रद्धा और परंपरा के प्रति सम्मान; परिश्रम से जीवन में बाद में सौभाग्य मिलता है। पिता या गुरुजनों से मतभेद संभव हैं।", "करियर के लिए अत्यंत प्रबल: कड़ी मेहनत, ज़िम्मेदारी, समय के साथ बना अधिकार, प्रशासन, कानून, इंजीनियरिंग या बड़े संगठनों में सफलता (स्वराशि/उच्च राशि में होने पर शश योग)।", "दृढ़ता से स्थिर, स्थायी लाभ और धन; प्रभावशाली, बड़ी आयु या वरिष्ठ मित्र। आयु के साथ आय बढ़ती है।", "खर्च, विदेश में निवास, अस्पतालों, आश्रमों या एकांत स्थानों में कार्य; आध्यात्मिक अनुशासन। नींद, पैरों और छिपी हुई हानियों का ध्यान रखें।"], "Rahu": ["अपरंपरागत, महत्वाकांक्षी और आकर्षक व्यक्तित्व, नए विचारों, तकनीक या विदेशी संस्कृति की ओर आकर्षित। पहचान को लेकर उलझन तथा कठिनाई से पहचानी जाने वाली स्वास्थ्य समस्याओं से सावधान रहें।", "आय के असामान्य स्रोत, विदेशी भाषाओं या मीडिया में कुशलता; निडर वाणी। अतिशयोक्ति, पारिवारिक विवाद और अनियमित भोजन से सावधान रहें।", "राहु के लिए सर्वश्रेष्ठ भावों में से एक: साहस, महत्वाकांक्षा, मीडिया, तकनीक, विपणन या संवाद में सफलता, तथा निडर पहल।", "जन्मस्थान से दूर या विदेश में निवास, असामान्य पारिवारिक जीवन; संपत्ति या वाहन में रुचि। मानसिक शांति और माता के स्वास्थ्य का ध्यान रखें।", "आविष्कारशील, अपरंपरागत बुद्धि; सट्टेबाज़ी, तकनीक या शोध में रुचि। संतान असामान्य ढंग से या देर से हो सकती है; जोखिमपूर्ण दांव से बचें।", "राहु के लिए उत्कृष्ट स्थिति: अपरंपरागत तरीकों से शत्रुओं पर विजय, प्रतिस्पर्धा, सेवा, चिकित्सा या कानून में सफलता।", "अपरंपरागत या विदेशी साथी तथा विदेशी संपर्कों वाला व्यवसाय; साझेदारियों में महत्वाकांक्षा। रिश्तों में स्पष्टता और विश्वास का ध्यान रखें।", "शोध और गूढ़ विद्या में गहरी रुचि; अचानक लाभ या हानि तथा अप्रत्याशित घटनाएँ। जोखिमपूर्ण उद्यमों और छिपी स्वास्थ्य समस्याओं से सावधान रहें।", "अपरंपरागत या विदेशी मान्यताएँ और गुरु, विदेश यात्रा; अनुकूल संबंध होने पर राजयोग बन सकता है। धर्म को लेकर बड़ों से टकराव से बचें।", "महत्वाकांक्षी, अपरंपरागत करियर, तकनीक, विदेशी कंपनियों या जनमाध्यमों में सफलता, तथा प्रतिष्ठा की तीव्र चाह। शॉर्टकट से प्रतिष्ठा की रक्षा करें।", "सामान्यतः राहु के लिए सबसे लाभकारी स्थानों में से एक: बड़ा लाभ, शक्तिशाली मित्र तथा महत्वाकांक्षाओं की पूर्ति, प्रायः तकनीक या विदेशी संपर्कों के माध्यम से।", "विदेश में निवास, आध्यात्मिक या गूढ़ गतिविधियाँ तथा असामान्य खर्च; नींद में गड़बड़ी और छिपी हानियों का ध्यान रखें।"], "Ketu": ["विरक्त, आध्यात्मिक और सहज-बोध वाला व्यक्तित्व जिसमें तीक्ष्ण अंतर्दृष्टि होती है; पहचान को लेकर अनिश्चितता महसूस हो सकती है। सामान्य जीवनी शक्ति का ध्यान रखें।", "धन या परिवार से विरक्ति, असामान्य वाणी या आहार; आध्यात्मिक अध्ययन। बचत और पारिवारिक सामंजस्य पर ध्यान दें।", "साहस, प्रबल सहज-बोध तथा स्वतंत्र प्रयासों से सफलता; रहस्यवाद या असामान्य कौशल में रुचि। भाई-बहनों से संबंध दूर हो सकते हैं।", "घर या जन्मस्थान से विरक्ति, निवास में बार-बार परिवर्तन; शांति की आंतरिक खोज। माता के स्वास्थ्य का ध्यान रखें।", "सहज-बोध वाली, शोध-प्रवृत्ति की बुद्धि तथा पूर्वजन्म का आध्यात्मिक पुण्य; संतान या प्रेम संबंधों में चुनौतियाँ या देरी आ सकती है।", "केतु के लिए अधिक प्रबल भावों में से एक: शत्रुओं पर विजय, तीक्ष्ण सहज-बोध, उपचार, शोध या सेवा में सफलता।", "आध्यात्मिक या असामान्य साझेदारी; विवाह और व्यवसाय में विरक्ति या गलतफहमियों का ध्यान रखें।", "गूढ़ विद्या, शोध और गुप्त विषयों में गहरी रुचि; अचानक परिवर्तन। दुर्घटनाओं और छिपी बीमारियों से सावधान रहें।", "अपरंपरागत श्रद्धा, कर्मकांडों से विरक्ति तथा गहरी आध्यात्मिक अंतर्दृष्टि; गुरुजनों या पिता से मतभेद संभव हैं।", "करियर में अचानक परिवर्तन, सहज-बोध या आध्यात्मिक रुचियों से निर्देशित कार्य; शोध, तकनीक या उपचार। जल्दबाज़ी के निर्णयों से बचें।", "आते-जाते लाभ, इच्छाओं से विरक्ति, विनोदी और बुद्धिमान; कुछ सार्थक मित्रताएँ।", "शास्त्रीय रूप से मोक्ष से जुड़ा हुआ: आध्यात्मिक मुक्ति, विदेशी भूमि और एकांतवास; आध्यात्मिक कार्यों पर खर्च।"]}, "ar": {"Sun": ["إحساس قوي بالذات، وقيادة، وحضور مهيب؛ حيوية جيدة ورغبة في أن يكون محترمًا. احذر الكبرياء وحدة المزاج، واعتنِ بالرأس والعينين والقلب.", "كسبٌ عبر السلطة أو الحكومة أو جهة الأب، وأسلوب كلام واثق وآمر. احذر الكلام القاسي في الأسرة والإنفاق للحفاظ على المكانة.", "شجاعة ومبادرة ونجاح بالجهد الذاتي؛ شهرة عبر التواصل أو الكتابة أو الرحلات القصيرة. قد تتسم العلاقة بالإخوة الأصغر بالتنافس.", "طموح لامتلاك عقار وبيت محترم، ونجاح بعيدًا عن مسقط الرأس. قد يتعكر السلام المنزلي بسبب صدام الأنا؛ ويحتاج القلب وصحة الأم إلى العناية.", "ذكاء حاد، وقدرة إبداعية واستشارية، واهتمام بالسياسة أو المضاربة. قد يكون الأولاد قليلين أو يتأخر إنجابهم؛ تجنّب المضاربة المتهورة.", "من أفضل بيوت الشمس: انتصار على الخصوم، ونجاح في الخدمة والإدارة والمنافسة، ومقاومة جيدة للمرض. احذر الإفراط في العمل والنزاعات في مكان العمل.", "شراكة وزواج بشريك قوي الإرادة أو مهتم بالمكانة الاجتماعية؛ مكاسب عبر التعامل مع الجمهور. قد تؤخر الأنا الزواج أو تسبب احتكاكًا في العلاقات.", "اهتمام بالمواضيع الخفية والبحث والميراث؛ تغيرات مفاجئة في المكانة. اعتنِ بالعينين والحيوية العامة؛ تجنّب المخاطرة غير الضرورية.", "حظ طيب والتزام بالدارما واحترام للمعلمين والأب؛ مكاسب عبر التعليم العالي أو القانون أو الدين. قد يجعل الشخص متعاليًا أخلاقيًا أو بعيدًا عن الأب.", "ممتاز للمسيرة المهنية: سلطة وشهرة ومناصب حكومية أو قيادية وتقدير عام — تكتسب الشمس هنا القوة الاتجاهية (ديغ بالا). احذر الغرور في العمل.", "مكاسب بجهد قليل، وأصدقاء ذوو نفوذ، وتحقيق للطموحات؛ دخل عبر الحكومة أو كبار الشخصيات. قد تقوم الصداقات على أساس المكانة.", "اهتمام بالروحانية والبلاد الأجنبية والعزلة؛ نفقات على المكانة أو السفر أو الأعمال الخيرية. تحتاج الثقة بالنفس والبصر إلى العناية؛ وقد يتأخر التقدير."], "Moon": ["طبيعة جذابة وحساسة واجتماعية، محبوبة بين الناس ومتقلبة المزاج. يعتمد التوازن العاطفي على قوة القمر (تزايده أو تناقصه).", "كلام لطيف وعذب، ومودة أسرية، ومكاسب عبر الجمهور أو الطعام أو السوائل أو التجارة. قد يتذبذب الدخل تبعًا لحالة الذهن.", "تواصل خيالي، وحب للسفر، ورابطة حانية بالإخوة؛ نجاح في الكتابة أو الإعلام أو الرحلات القصيرة. قد تبدد تقلبات المزاج الجهد المبذول.", "من أفضل بيوت القمر (القوة الاتجاهية): بيت سعيد، وراحة، ومركبات، ورابطة وثيقة بالأم، وطمأنينة نفسية.", "ذكاء عاطفي، وإبداع، ومودة للأولاد (غالبًا البنات)؛ مكاسب عبر الجمهور أو الأدوار الاستشارية. احذر الإفراط في الحساسية العاطفية.", "طبيعة حانية تميل إلى الخدمة، تناسب الرعاية الصحية أو الخدمة العامة؛ يحتاج الهضم والمعدة إلى العناية، وقد يؤثر التوتر العاطفي على الصحة.", "شريك عاطفي وجذاب وحاجة قوية إلى الرفقة؛ نجاح في التعامل مع الجمهور. تحتاج تقلبات مزاج الشريك إلى الصبر.", "عقل عميق وحدسي وكتوم؛ اهتمام بالعلوم الخفية وإمكانية الميراث. تقلبات عاطفية بين صعود وهبوط، والعناية بالعينين وسوائل الجسم مطلوبة.", "طبيعة تقية ومحبوبة ومحظوظة، وحب للحج والتعلم، وأولاد صالحون، ودعم من الأم. السفر إلى الخارج مرجّح.", "شعبية بين الناس، ونجاح في الأعمال والضيافة والمهن التي تواجه الجمهور أو مهن الرعاية؛ مسار مهني متغير بتنقلات كثيرة. تعتمد السمعة على قوة القمر.", "أصدقاء كثيرون (غالبًا من النساء)، وتحقيق للأمنيات، ومكاسب ثابتة عبر الجمهور والعلاقات. قد يتذبذب الدخل لكنه يميل إلى الارتفاع مع الوقت.", "حياة داخلية خاصة وخيالية، وانجذاب إلى الأماكن الأجنبية والعمل الخيري والعزلة الروحية. يحتاج النوم والنفقات والانعزال العاطفي إلى العناية."], "Mars": ["طاقة وشجاعة وشخصية جريئة ونشطة؛ قيادة فطرية في المجالات البدنية أو التقنية. احذر نفاد الصبر والغضب والإصابات أو الندوب البسيطة في الرأس. (يُحسب ضمن مانغال دوشا)", "كلام صريح وحازم، ومال يُكسب بالجهد أو الأرض أو العمل التقني. أهم المحاذير هي الخلافات الأسرية والإنفاق الاندفاعي. (يُحسب ضمن مانغال دوشا في الممارسة الهندية الجنوبية)", "من أفضل بيوت المريخ: شجاعة كبيرة ومبادرة ونجاح بالجهد الذاتي؛ مناسب للرياضة أو الجيش أو الشرطة أو الهندسة. قد تتسم العلاقة بالإخوة بالتنافس.", "عقار وأرض ومركبات بالجهد؛ رغبة قوية في امتلاك بيت خاص. يحتاج السلام المنزلي وصحة الأم إلى العناية؛ تجنّب الخلافات المنزلية. (يُحسب ضمن مانغال دوشا)", "ذكاء حاد واستراتيجي، ودافع إبداعي تنافسي؛ اهتمام بالرياضة أو التكنولوجيا. قد يأتي الإنجاب بشيء من الصعوبة؛ تجنّب المضاربة المتهورة.", "ممتاز للتغلب على الخصوم والفوز في المنافسات أو القضايا القانونية؛ نجاح في الخدمة أو الجراحة أو الشرطة أو الجيش. احذر ضغط الدم والالتهابات.", "شريك متحمس ونشيط، وأسلوب جريء في الشراكات والأعمال. يحتاج الاحتكاك أو السيطرة في الزواج إلى عناية؛ والصبر ضروري. (يُحسب ضمن مانغال دوشا)", "اهتمام بالبحث أو الجراحة أو العلوم الخفية أو العمل في الأزمات؛ إمكانية الميراث أو المكاسب المفاجئة. احذر الحوادث والعمليات الجراحية والخلافات حول المال المشترك. (يُحسب ضمن مانغال دوشا)", "طبيعة نشطة ومبدئية تدافع عن معتقداتها؛ مكاسب عبر الأرض أو التجارة أو السفر. قد تحدث خلافات مع الأب أو المعلمين؛ تجنّب التصلب في الرأي.", "ممتاز للمسيرة المهنية (القوة الاتجاهية): طاقة وقيادة وإنجاز في الهندسة أو الجيش أو الرياضة أو الجراحة أو الإدارة؛ قادر على تأسيس مؤسسات. احذر الخلافات مع السلطة.", "مكاسب قوية عبر الجهد والعقار وأصدقاء ذوي نفوذ؛ تتحقق الطموحات بالعمل الجاد. قد يتسم الإخوة الأكبر أو الأصدقاء بالتنافس.", "طاقة تُصرف في الشؤون الأجنبية أو المستشفيات أو الممارسة الروحية أو العمل الخفي؛ قد ترتفع النفقات. اعتنِ بالنوم والغضب والأعداء الخفيين. (يُحسب ضمن مانغال دوشا)"], "Mercury": ["شخصية ذكية وظريفة وشابة النزعة ومتواصلة؛ قدرة جيدة على التعلم وموهبة في التجارة أو الكتابة أو الخطابة. قد يكون الشخص قلقًا أو عصبيًا.", "كلام فصيح ومقنع، ومهارة في اللغات والحسابات والتجارة؛ كسب عبر الذكاء. احذر أن يتحول الذكاء إلى جدال.", "تواصل ممتاز، وكتابة، وإعلام، وتجارة، وسفر قصير؛ لباقة وسرعة بديهة. غالبًا ما تكون العلاقة بالإخوة فكرية وحيوية.", "تعليم، وبيت مثقف، ونجاح في العقار أو المركبات أو العمل الأدبي، وأم حانية. قد يجلب قلقًا ذهنيًا في المنزل.", "ذكاء حاد، ومهارة في الرياضيات والتحليل والأدوار الاستشارية أو الإدارية؛ طلاب متفوقون. قد يكون الأولاد أذكياء وحسني التواصل.", "عمل تحليلي ودقيق التفاصيل: الحسابات أو القانون أو الصحة أو الخدمة؛ قادر على التفوق في الجدال على الخصوم. احذر التوتر العصبي وحساسية الجلد والهضم.", "شريك شاب النزعة وذكي، ونجاح في التجارة والتفاوض والشراكات التجارية. تستفيد العلاقات من التواصل الجيد.", "بحث وتحقيق ودراسة للعلوم الخفية وعمر مديد؛ إمكانية مكاسب من الميراث أو التأمين. يحتاج القلق والتفكير الكتوم إلى توازن.", "تعليم عالٍ وفلسفة وقانون ونشر وتدريس؛ اهتمامات متعددة وقدرة إبداعية وعلمية. قد يُفرط في التعامل مع الإيمان بعقلانية مفرطة.", "مسيرة مهنية عبر التواصل أو التجارة أو تقنية المعلومات أو المحاسبة أو الكتابة أو التدريس؛ ذكي ومحظوظ في العمل — يكتسب عطارد القوة الاتجاهية في البيت الأول، لكنه يؤدي جيدًا هنا أيضًا.", "مكاسب عبر التجارة والعلاقات والرياضيات والتواصل؛ أصدقاء كثيرون وتحقق للأمنيات. قد يأتي الدخل من مصادر متعددة.", "عقل تأملي وفلسفي، واهتمام باللغات الأجنبية أو البحث أو الروحانية. يحتاج القلق والنفقات على التعلم وفجوات التواصل إلى العناية."], "Jupiter": ["من أفضل بيوت المشتري (القوة الاتجاهية): حكمة ووقار وأخلاق حسنة وتأثير حامٍ على الخريطة كلها؛ محترم كمرشد أو معلم. احذر زيادة الوزن والإفراط في التفاؤل.", "ثروة، وأسرة مثقفة، وكلام فصيح وصادق، ونجاح في التدريس أو القانون أو التمويل. يميل المال إلى التراكم مع الوقت.", "حكمة في التواصل والكتابة؛ علاقة جيدة بالإخوة. قد تكون الجهود بطيئة أو يقل كرم المشتري هنا؛ يلزم جهد متواصل.", "بيت سعيد ومريح، وتعليم جيد، وعقار ومركبات، وأم حانية؛ رضا داخلي. من أوضاع المشتري الزاويّة القوية.", "ممتاز للذكاء والأولاد والتعليم والنصيحة والممارسة الروحية؛ حكم سديد ومكانة محترمة.", "انتصار عبر الحكمة والأخلاق، يناسب الخدمة أو القانون أو الطب أو الإرشاد. تعتبره النصوص الكلاسيكية أضعف هنا؛ احذر الديون والوزن وصحة الكبد.", "شريك حكيم وفاضل ومتعلم غالبًا؛ نجاح في الشراكات والقانون والاستشارات. يُسدد المشتري نظره من هنا إلى الطالع، فيدعم الصحة والأخلاق.", "عمر مديد، واهتمام بالمعرفة الروحية والخفية، وإمكانية الميراث. تعتبره النصوص الكلاسيكية أقل راحة؛ تأتي النتائج بعد تجاوز العقبات.", "من أكثر الأوضاع حظًا: الدارما والإيمان ومعلمون صالحون وأولاد وكرم وحظ عبر التعليم العالي أو القانون أو الدين أو السفر.", "مسيرة مهنية مشرفة في التدريس أو القانون أو التمويل أو الاستشارة أو الإدارة؛ محترم وأخلاقي وقادر على تأسيس مؤسسات. تميل الترقيات إلى الحدوث بثبات.", "مكاسب كبيرة، وتحقق للأمنيات، وأصدقاء متعلمون وذوو نفوذ؛ يرتفع الدخل مع التقدم في العمر. وضع مفيد جدًا للازدهار.", "كرم وعمل خيري ونمو روحي واهتمام بالموكشا (الخلاص)؛ نفقات على القضايا الخيرية والسفر إلى الخارج. قد تحتاج المدخرات المادية إلى العناية."], "Venus": ["سحر وجمال وذوق فني وطبيعة لطيفة واجتماعية؛ رغد وحظ طيب في العلاقات. احذر الانغماس في الملذات والغرور.", "ثروة وأسرة سعيدة وكلام عذب وكسب عبر الفنون أو الرفاهية أو الجمال أو التمويل؛ حب للطعام الجيد. احذر الإسراف في الإنفاق.", "تواصل فني وإبداعي، وحب للموسيقى والإعلام؛ إخوة عاطفيون. قد تكون الشجاعة لينة؛ يأتي النجاح عبر السحر والمهارة.", "من أفضل بيوت الزهرة: بيت جميل، ومركبات، ورغد، وأم محبة، وسعادة منزلية؛ تعليم جيد في الفنون.", "إبداع ورومانسية وذكاء فني وسعادة بالأولاد؛ نجاح في الترفيه أو التصميم أو المضاربة بحذر.", "تعتبر النصوص الكلاسيكية الزهرة ضعيفة هنا: قد تواجه العلاقات عقبات أو تأتي عبر العمل؛ يناسب الخدمة في مجال الجمال أو الصحة أو الضيافة. احذر السكر والانغماس في الملذات.", "البيت الطبيعي للزواج: شريك جذاب وعاطفي ومتعة في الشراكة والأعمال والتعامل مع الجمهور. وازن بين الرومانسية والمسؤولية.", "مكاسب عبر الزوج أو الميراث أو الموارد المشتركة؛ اهتمام بالملذات الخفية أو العلوم الخفية. احذر على الصحة الإنجابية والعلاقات السرية.", "حظ عبر الفنون أو زوج مثقف أو علاقات أجنبية؛ كريم ورقيق ومخلص. سفر للمتعة أو التعلم.", "مسيرة مهنية في الفنون أو الموضة أو التصميم أو الإعلام أو الضيافة أو التمويل أو الدبلوماسية؛ سحر وشعبية بين الناس. نجاح عبر النساء أو الشركاء.", "مكاسب عبر الفنون والرفاهية والشركاء والأصدقاء ذوي النفوذ؛ تحقق للرغبات ودخل مريح.", "موضع مفضل للزهرة تقليديًا: رغد الفراش والراحة، والسفر إلى الخارج، والتعبد الروحي عبر الجمال. احذر الإسراف في الإنفاق والعلاقات السرية."], "Saturn": ["طبيعة جادة وناضجة وكادحة وصبورة؛ يأتي النجاح ببطء لكنه يدوم. احذر التشاؤم والوحدة والمشكلات الصحية المزمنة؛ يكون قويًا إذا كان زحل في برجه الخاص أو في شرفه.", "ثروة تُبنى ببطء عبر الانضباط والادخار؛ أسلوب كلام متزن وحذر. تحتاج المسؤوليات الأسرية والتعليم المتأخر والبصر إلى العناية.", "من أفضل بيوت زحل: مثابرة وشجاعة عبر التحمل ونجاح بعد جهد متواصل؛ تخطيط طويل الأمد. قد تكون العلاقة بالإخوة متباعدة.", "مسؤوليات في المنزل، وتأخر في العقار أو المركبات، ورابطة جادة بالأم؛ تنمو الطمأنينة النفسية مع التقدم في العمر. قد يأتي النجاح بعيدًا عن مسقط الرأس.", "ذكاء جاد وعملي وانضباط في الدراسة؛ قد يتأخر الإنجاب أو يقل عدد الأولاد، وينبغي تجنّب المضاربة.", "ممتاز للتغلب على الخصوم بالمثابرة؛ يناسب الخدمة أو العمل اليدوي أو القانون أو الرعاية الصحية. تميل المشكلات الصحية إلى أن تكون مزمنة لكن يمكن ضبطها بالانضباط.", "شريك ناضج ووفي أو أكبر سنًا؛ قد يتأخر الزواج لكنه مستقر. نجاح في الشراكات التجارية طويلة الأمد (القوة الاتجاهية لزحل).", "عمر مديد، واهتمام بالبحث والمواضيع الخفية؛ تحول بطيء ودائم. يحتاج تأخر الميراث والأمراض المزمنة إلى الصبر.", "إيمان منضبط واحترام للتقاليد؛ يأتي الحظ متأخرًا في الحياة عبر الجهد. قد تحدث خلافات مع الأب أو المعلمين.", "قوي جدًا للمسيرة المهنية: عمل جاد ومسؤولية وسلطة تُبنى مع الوقت، ونجاح في الإدارة أو القانون أو الهندسة أو المؤسسات الكبيرة (شاشا يوغا إذا كان في برجه الخاص أو في شرفه).", "مكاسب ثابتة ودائمة وثروة عبر المثابرة؛ أصدقاء ذوو نفوذ أو أكبر سنًا أو أعلى مكانة. يرتفع الدخل مع التقدم في العمر.", "نفقات، وإقامة في الخارج، وعمل في المستشفيات أو الآشرامات أو الأماكن المعزولة؛ انضباط روحي. يحتاج النوم والقدمان والخسائر الخفية إلى العناية."], "Rahu": ["شخصية غير تقليدية وطموحة وجذابة، تنجذب إلى الأفكار الجديدة أو التكنولوجيا أو الثقافة الأجنبية. احذر التشوش في الهوية والمشكلات الصحية التي يصعب تشخيصها.", "مصادر دخل غير معتادة، ومهارة في اللغات الأجنبية أو الإعلام؛ كلام جريء. احذر المبالغة والخلافات الأسرية وعدم انتظام الأكل.", "من أفضل بيوت راهو: شجاعة وطموح ونجاح في الإعلام أو التكنولوجيا أو التسويق أو التواصل، ومبادرة جريئة.", "استقرار بعيدًا عن مسقط الرأس أو في الخارج، وحياة منزلية غير معتادة؛ اهتمام بالعقار أو المركبات. تحتاج الطمأنينة النفسية وصحة الأم إلى العناية.", "ذكاء مبتكر وغير تقليدي؛ اهتمام بالمضاربة أو التكنولوجيا أو البحث. قد يأتي الإنجاب بطريقة غير معتادة أو متأخرة؛ تجنّب المراهنات الخطرة.", "وضع ممتاز لراهو: انتصار على الخصوم، ونجاح في المنافسة أو الخدمة أو الطب أو القانون بوسائل غير تقليدية.", "شريك غير تقليدي أو أجنبي، وأعمال ذات صلات أجنبية؛ طموح في الشراكات. تحتاج الوضوح والثقة في العلاقات إلى العناية.", "اهتمام عميق بالبحث والعلوم الخفية؛ مكاسب أو خسائر مفاجئة وأحداث غير متوقعة. الحذر من المشاريع الخطرة والمشكلات الصحية الخفية.", "معتقدات ومعلمون غير تقليديين أو أجانب، وسفر إلى الخارج؛ يمكن أن يكوّن راجا يوغا عند اتصاله الجيد. تجنّب الخلاف مع الكبار حول الإيمان.", "مسيرة مهنية طموحة وغير تقليدية، ونجاح مع التكنولوجيا أو الشركات الأجنبية أو الإعلام الجماهيري، ودافع قوي نحو المكانة. احذر على السمعة من اختصار الطرق.", "عمومًا من أكثر مواضع راهو فائدة: مكاسب كبيرة، وأصدقاء أقوياء، وتحقق للطموحات، غالبًا عبر التكنولوجيا أو الشبكات الأجنبية.", "إقامة في الخارج، ومساعٍ روحية أو في العلوم الخفية، ونفقات غير معتادة؛ تحتاج اضطرابات النوم والخسائر الخفية إلى العناية."], "Ketu": ["شخصية منعزلة وروحية وحدسية ذات بصيرة حادة؛ قد تشعر بعدم اليقين تجاه هويتها. اعتنِ بالحيوية العامة.", "زهد في المال أو الأسرة، وكلام أو نظام غذائي غير معتاد؛ تعلم روحي. تحتاج المدخرات والانسجام الأسري إلى الاهتمام.", "شجاعة وحدس قوي ونجاح عبر الجهد المستقل؛ اهتمام بالتصوف أو المهارات غير المعتادة. قد تكون العلاقة بالإخوة متباعدة.", "زهد في المنزل أو مسقط الرأس، وتغييرات متكررة في مكان الإقامة؛ بحث داخلي عن السلام. تحتاج صحة الأم إلى العناية.", "ذكاء حدسي وميّال للبحث، وفضل روحي من حياة سابقة؛ قد يجلب الأولاد أو الرومانسية تحديات أو تأخيرًا.", "من بيوت كيتو الأقوى: انتصار على الأعداء، وغرائز حادة، ونجاح في الشفاء أو البحث أو الخدمة.", "شراكة روحية أو غير معتادة؛ يحتاج الزهد أو سوء الفهم في الزواج والأعمال إلى العناية.", "اهتمام عميق بالعلوم الخفية والبحث والأمور الخفية؛ تحولات مفاجئة. احذر الحوادث والأمراض الخفية.", "إيمان غير تقليدي، وزهد في الطقوس، وبصيرة روحية عميقة؛ قد تحدث خلافات مع المعلمين أو الأب.", "تغيرات مفاجئة في المسيرة المهنية، وعمل موجَّه بالحدس أو الاهتمامات الروحية؛ البحث أو التكنولوجيا أو الشفاء. تجنّب القرارات المفاجئة.", "مكاسب تأتي وتذهب، وزهد في الرغبات، وذكاء وظرافة؛ صداقات قليلة لكنها ذات معنى.", "مرتبط تقليديًا بالموكشا (الخلاص): تحرر روحي، وبلاد أجنبية، وخلوات؛ نفقات على القضايا الروحية."]}, "zh": {"Sun": ["强烈的自我意识、领导力与庄重的气度；活力充沛，渴望受人尊重。需留意骄傲与急躁的脾气，并照顾好头部、眼睛与心脏。", "通过权威、政府部门或父亲一方获得收入，说话方式自信而有威严。需留意家庭中言辞过于严厉，以及为维持身份地位而过度花费。", "勇气与主动性带来靠自身努力获得的成功；通过沟通、写作或短途旅行获得名声。与弟妹的关系可能带有竞争色彩。", "渴望拥有产业与体面的家庭，成功往往在出生地之外取得。家中的平静可能因自我意识的冲突而受扰；需留意心脏及母亲的健康。", "敏锐的智慧、创造力与建言能力，对政治或投机有兴趣。子女可能较少或较晚出现；应避免鲁莽的投机行为。", "太阳在此宫位表现最佳之一：战胜对手，在服务、行政与竞争中获得成功，抵抗疾病的能力较强。需留意工作过度与职场冲突。", "伴侣关系与婚姻中的对象意志坚强或看重身份地位；通过与公众打交道获得收益。关系中的自我意识可能延误婚姻或引发摩擦。", "对隐秘学问、研究与遗产感兴趣；地位可能骤然变化。需照顾眼睛与整体活力；避免不必要的冒险。", "福气深厚，正法（dharma）具足，敬重师长与父亲；通过高等教育、法律或宗教获得收益。也可能使人自以为是，或与父亲疏远。", "极利于事业：权威、名声、政府或领导职位及公众认可——太阳在此宫获得方位力量（Dig Bala）。需防范职场中的傲慢。", "无需太多努力即可获益，结交有影响力的朋友，志向得以实现；收入来自政府部门或地位较高的人士。友谊可能带有身份地位的考量。", "对灵性修行、异国他乡与独处感兴趣；花费用于身份地位、旅行或慈善。自信心与视力需要留意；认可可能来得较晚。"], "Moon": ["富有魅力、敏感而善于社交的性情，深受人们喜爱，情绪易变。情绪的平衡取决于月亮的强弱（盈亏）。", "言语温和甜美，家庭情感深厚，通过公众、食品、液体或贸易获得收益。收入可能随心情起伏而波动。", "富有想象力的沟通方式，热爱旅行，与兄弟姐妹关系亲密；在写作、媒体或短途旅行中获得成功。情绪波动可能使精力分散。", "月亮在此宫表现最佳之一（方位力量）：家庭幸福、生活舒适、拥有车辆，与母亲关系亲密，内心平静。", "情商高、富有创造力，疼爱子女（常为女儿）；通过公众事务或顾问角色获益。需防范在感情上过度敏感。", "富有关怀之心、乐于服务的性情，适合从事医疗或公共服务；需留意消化系统与胃部健康，情绪压力可能影响身体。", "伴侣情感丰富、富有魅力，对陪伴的需求强烈；在公众事务中获得成功。伴侣的情绪或善变需要耐心对待。", "内心深沉、直觉敏锐且富有隐秘感；对神秘学感兴趣，可能获得遗产。情绪起伏较大，需留意眼睛与体内水液。", "虔诚、受人喜爱且福气深厚的性情，热爱朝圣与求学，子女良善，得到母亲的支持。很可能有出国旅行的机会。", "深受公众喜爱，在商业、酒店服务、面向公众或关怀性质的职业中获得成功；职业道路多变、常有变动。声誉取决于月亮的强弱。", "朋友众多（常以女性为主），心愿得以实现，通过公众与人脉获得稳定收益。收入可能有所波动，但总体呈上升趋势。", "内心生活私密而富有想象力，向往异国他乡、慈善事业与灵修静修。需留意睡眠、开支与情感上的孤立感。"], "Mars": ["精力充沛、勇气十足，性格大胆而活跃；在体能或技术领域具有天生的领导力。需留意急躁、易怒，以及头部的轻微受伤或疤痕。（计入 Mangal Dosha 火星凶象。）", "言辞直率而有力，通过努力、土地或技术工作赚取金钱。家庭中的争吵与冲动消费是主要需留意之处。（在南印度体系中计入 Mangal Dosha 火星凶象。）", "火星在此宫表现最佳之一：勇气过人、主动进取，靠自身努力获得成功；擅长体育、军事、警务或工程领域。与兄弟姐妹的关系可能带有竞争色彩。", "通过努力获得产业、土地与车辆；强烈渴望拥有自己的家。家庭的平静与母亲的健康需要留意；应避免家庭争执。（计入 Mangal Dosha 火星凶象。）", "头脑敏锐、善于策略，创造力中带有竞争意识；对体育或科技感兴趣。子女的到来可能有些波折；应避免鲁莽的投机。", "极利于战胜对手、在竞争或法律事务中获胜；在服务、外科、警务或军队中获得成功。需留意血压与炎症问题。", "伴侣热情而充满活力，对待合作与事业的态度大胆果敢。婚姻中的摩擦或主导倾向需要留意；耐心至关重要。（计入 Mangal Dosha 火星凶象。）", "对研究、外科、神秘学或危机处理工作感兴趣；可能获得遗产或意外之财。需防范意外事故、手术，以及因共同财产引发的冲突。（计入 Mangal Dosha 火星凶象。）", "积极而有原则的性情，愿为信念而抗争；通过土地、贸易或旅行获益。与父亲或师长可能产生分歧；应避免固执己见。", "极利于事业（方位力量）：精力充沛、善于指挥，在工程、军事、体育、外科或管理领域有所成就；有能力创办机构。需留意与权威人士的冲突。", "通过努力、产业与有影响力的朋友获得可观收益；志向靠辛勤努力得以实现。兄姐或朋友之间可能存在竞争。", "精力花费在海外事务、医院、灵修或隐秘工作上；开支可能较高。需留意睡眠、易怒情绪与暗中的敌人。（计入 Mangal Dosha 火星凶象。）"], "Mercury": ["聪明风趣、性情年轻且善于沟通；学习能力强，在贸易、写作或演说方面颇具天赋。可能容易焦躁不安或紧张。", "口才流利、善于说服，在语言、账目与贸易方面颇具才能；凭智慧获得收入。需防范机智演变为争执。", "在沟通、写作、媒体、商业与短途旅行方面表现出色；处事圆融、思维敏捷。与兄弟姐妹的关系通常充满智性交流，气氛活跃。", "重视教育，家中书香氛围浓厚，在产业、车辆或文学工作上有所成就，母亲关怀备至。也可能使家中弥漫思绪不安的气氛。", "头脑敏锐，擅长数学、分析及顾问或行政类工作；是优秀的学生。子女可能聪慧且善于表达。", "从事分析性、注重细节的工作：账目、法律、医疗或服务；能在辩论中胜过对手。需留意神经紧张，以及皮肤与消化系统的敏感问题。", "伴侣年轻而聪慧，在贸易、谈判与商业合作中获得成功。良好的沟通有益于关系的发展。", "从事研究、调查与神秘学的探索，寿命较长；可能从遗产或保险中获益。忧虑与思虑过密的倾向需要加以平衡。", "涉猎高等教育、哲学、法律、出版与教学；兴趣广泛，兼具创造力与科学才能。也可能将信仰过度理性化。", "事业发展于沟通、贸易、信息技术、会计、写作或教学领域；聪慧且工作顺遂——水星在第一宫获得方位力量（Dig Bala），但在此宫同样表现良好。", "通过贸易、人脉、数学与沟通获得收益；朋友众多，心愿得以实现。收入可能来自多个渠道。", "内省而富哲思的头脑，对外语、研究或灵性修行感兴趣。忧虑、用于学习的开支及沟通上的隔阂需要留意。"], "Jupiter": ["木星在此宫表现最佳之一（方位力量）：智慧、庄重、品格良好，并对整张命盘起到庇护作用；作为引导者或老师受人尊敬。需留意体重增加与过度乐观。", "财富充裕，家庭有教养，言语流畅而诚实，在教学、法律或金融领域获得成功。财富往往随时间逐渐积累。", "在沟通与写作中展现智慧；与兄弟姐妹关系良好。木星在此宫的努力见效较慢，其慷慨特质也有所减弱；需要持之以恒的努力。", "家庭幸福舒适，教育良好，拥有产业与车辆，母亲关怀备至；内心知足常乐。这是木星强有力的角宫（角度宫位）之一。", "极利于智慧、子女、教育、建言与灵修实践；判断力良好，地位受人尊敬。", "凭借智慧与道德取得胜利，适合从事服务、法律、医学或咨询工作。古典典籍认为木星在此宫力量较弱；需留意债务、体重与肝脏健康。", "伴侣智慧而有德行，通常受过良好教育；在合作关系、法律与咨询领域获得成功。木星由此宫相望上升点，有助于健康与品格。", "寿命较长，对灵性与隐秘学问感兴趣，可能获得遗产。古典典籍认为此位置较为不利；成果往往在克服障碍之后才会显现。", "最为吉祥的位置之一：正法（dharma）、信仰、良师、子女、慷慨，以及通过高等教育、法律、宗教或旅行获得的福气。", "在教学、法律、金融、顾问或行政领域从事受人尊敬的事业；为人正直有德，有能力创办机构。晋升往往稳步而来。", "获得可观收益，心愿得以实现，结交博学而有影响力的朋友；收入随年岁增长而提升。对财富积累而言是极为有利的位置。", "慷慨大方、乐于慈善，灵性不断成长，对解脱（moksha）感兴趣；花费多用于善事与出国旅行。物质储蓄方面可能需要留意。"], "Venus": ["富有魅力、容貌姣好，具备艺术品味，性情温和善于社交；生活舒适，感情关系中福气良好。需留意放纵享乐与虚荣心。", "财富充裕，家庭幸福，言语甜美，通过艺术、奢侈品、美容或金融获得收入；喜爱美食。需防范过度消费。", "沟通方式富有艺术气息与创造力，热爱音乐与媒体；与兄弟姐妹感情深厚。勇气方面可能较为柔和；成功靠魅力与技巧取得。", "金星在此宫表现最佳之一：家中环境优美，拥有车辆，生活舒适，母亲慈爱，家庭幸福美满；在艺术方面接受良好教育。", "富有创造力，浪漫多情，具备艺术天赋，因子女而感到喜悦；在娱乐、设计领域获得成功，投机则需谨慎。", "古典典籍认为金星在此宫力量较弱：感情关系可能面临阻碍，或通过工作结缘；适合从事美容、医疗或酒店服务行业。需留意糖分摄入与放纵享乐。", "婚姻的自然宫位：伴侣富有魅力且情深意重，在合作关系、事业与公众事务中获得愉悦。需在浪漫与责任之间取得平衡。", "通过配偶、遗产或共同资源获得收益；对隐秘的享乐或神秘学感兴趣。需留意生殖健康，并防范隐秘的感情纠葛。", "通过艺术、有教养的配偶或海外关系获得福气；为人慷慨、优雅而虔诚。常因享乐或求学而出行。", "事业发展于艺术、时尚、设计、媒体、酒店服务、金融或外交领域；在公众面前富有魅力、深受欢迎。成功往往借助女性或伴侣的助力。", "通过艺术、奢侈品、伴侣与有影响力的朋友获得收益；心愿得以满足，收入宽裕舒适。", "古典上金星在此宫备受眷顾：享有床笫与休憩之乐，出国旅行，通过美的事物获得灵性上的虔诚。需留意过度消费与隐秘的感情关系。"], "Saturn": ["性情严肃、成熟、勤奋而有耐心；成功来得缓慢，却能持久。需留意悲观情绪、孤独感与慢性健康问题；若土星入本宫或入旺，则力量强大。", "通过自律与储蓄逐步积累财富；说话方式沉稳而谨慎。家庭责任、延迟的教育与视力问题需要留意。", "土星在此宫表现最佳之一：坚韧不拔，凭借毅力获得勇气，经持续努力后取得成功；擅长长远规划。与兄弟姐妹的关系可能较为疏远。", "家庭责任较重，产业或车辆的获得有所延迟，与母亲的关系较为严肃；内心的平静随年岁增长而加深。成功可能在出生地之外获得。", "头脑严谨务实，治学有纪律；子女可能来得较晚或较少，应避免投机行为。", "凭借坚持不懈战胜对手的极佳位置；适合从事服务、劳动、法律或医疗工作。健康问题往往为慢性，但可通过自律加以管理。", "伴侣成熟忠诚，或年长于自己；婚姻可能较晚，但稳固持久。在长期商业合作中获得成功（土星在此获方位力量）。", "寿命较长，对研究与隐秘学问感兴趣；转变缓慢却持久。遗产的延迟与慢性疾病需要耐心应对。", "信仰虔诚而有纪律，尊重传统；福气需靠努力在人生后期才逐渐显现。与父亲或师长可能产生分歧。", "对事业极为有利：勤奋工作、责任心强，权威随时间逐步建立，在行政、法律、工程或大型机构中获得成功（若入本宫或入旺，则形成 Shasha 瑜伽）。", "凭借坚持获得稳定持久的收益与财富；结交有影响力的年长或资深朋友。收入随年岁增长而提升。", "开支较多，可能旅居海外，在医院、静修院或偏僻之地工作；灵修戒律严谨。睡眠、双脚与隐性损失需要留意。"], "Rahu": ["性格不落俗套、野心勃勃且极具魅力，热衷于新观念、科技或异国文化。需留意自我认同上的困惑，以及难以诊断的健康问题。", "收入来源不同寻常，擅长外语或媒体工作；言辞大胆。需留意言过其实、家庭纠纷与饮食不规律。", "罗睺在此宫表现最佳之一：勇气与野心兼备，在媒体、科技、营销或传播领域获得成功，行事大胆果敢。", "定居于出生地之外或海外，家庭生活方式不同寻常；对产业或车辆感兴趣。内心平静与母亲的健康需要留意。", "头脑富于创造力、不拘一格；对投机、科技或研究感兴趣。子女的到来可能方式特殊或有所延迟；应避免高风险的赌注。", "罗睺极佳的位置：战胜对手，通过非传统的方式在竞争、服务、医学或法律领域获得成功。", "伴侣特立独行或来自异国，事业与海外有所关联；在合作关系中野心勃勃。关系中的坦诚与信任需要留意。", "对研究与神秘学有着浓厚兴趣；可能出现突如其来的得失与意外事件。需谨慎对待高风险的事业，并留意隐性的健康问题。", "信仰与师承不落传统或来自异国，常有出国旅行；若配置良好，可形成 Raja 瑜伽。应避免因信仰问题与长辈发生冲突。", "事业雄心勃勃、别具一格，在科技、外资企业或大众媒体领域获得成功，对身份地位有强烈的追求。需谨防为求捷径而损害声誉。", "通常是罗睺最为有利的位置之一：获得巨大收益，结交有权势的朋友，志向得以实现，往往借助科技或海外人脉。", "旅居海外，追求灵修或神秘学，开支方式不同寻常；睡眠困扰与隐性损失需要留意。"], "Ketu": ["性情超然、富有灵性且直觉敏锐，洞察力强；可能对自我认同感到不确定。需留意整体的活力。", "对财富或家庭抱持超然的态度，言语或饮食方式不同寻常；专注于灵性学习。储蓄与家庭和睦需要留意。", "勇气十足、直觉强烈，凭借独立努力获得成功；对神秘主义或特殊技能感兴趣。与兄弟姐妹的关系可能较为疏远。", "对家庭或出生地抱持超然的态度，居所常有变动；内心不断寻求平静。母亲的健康需要留意。", "直觉敏锐、富有研究精神，具备前世修来的灵性功德；子女或感情方面可能带来挑战或延迟。", "计都在此宫力量较强之一：战胜敌人，本能敏锐，在疗愈、研究或服务领域获得成功。", "伴侣关系带有灵性色彩或不同寻常；婚姻与事业合作中的疏离感或误解需要留意。", "对神秘学、研究与隐秘事务有着浓厚兴趣；可能经历突如其来的转变。需防范意外事故与隐性疾病。", "信仰不落俗套，对仪式抱持超然的态度，具备深厚的灵性洞见；与师长或父亲可能产生分歧。", "事业可能突然发生变化，工作受直觉或灵性兴趣引导；涉及研究、科技或疗愈领域。应避免仓促做决定。", "收益时有时无，对欲望抱持超然的态度，机智而聪慧；拥有为数不多却意义深厚的友谊。", "古典上与解脱（moksha）密切相关：灵性解脱、异国他乡与静修；花费多用于灵性事业。"]}}};
